/* Full app rebuild layer. Dark, blocky, lime, and built around the Linkr pixel bot. */

:root {
  --sm-lime: #ccff00;
  --sm-black: #030403;
  --sm-muted: #aaa9a1;
  --sm-cream: #f7f4e5;
  --sm-panel: #090a08;
  --sm-panel-2: #11130e;
  --sm-hero-header-bg: #0d0c0b;
  --sm-line: rgb(249 241 218 / 18%);
  --sm-line-strong: rgb(249 241 218 / 32%);
  --sm-black-line: rgb(21 20 18 / 86%);
  --sm-grid-line: rgb(204 255 0 / 1.4%);
  --sm-radius: 6px;
  --sm-radius-sm: 4px;
}

body .app-wallet-add-menu {
  z-index: 1000 !important;
  isolation: isolate;
  width: min(19rem, calc(100vw - 2rem));
  padding: 0.45rem;
  border: 0;
  border-radius: 1rem;
  background: var(--popover);
  color: var(--popover-foreground);
  box-shadow: 0 18px 50px rgb(0 0 0 / 0.14);
}

body .app-wallet-add-menu-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.8rem;
  border-radius: 0.75rem;
  cursor: pointer;
}

body .app-wallet-add-menu-item > svg {
  margin-top: 0.15rem;
  color: var(--primary);
}

body .app-wallet-add-menu-item span {
  display: grid;
  gap: 0.15rem;
}

body .app-wallet-add-menu-item strong {
  font-size: 0.85rem;
  font-weight: 700;
}

body .app-wallet-add-menu-item small {
  color: var(--muted-foreground);
  font-size: 0.72rem;
  line-height: 1.35;
}

body .app-wallet-import-key-field {
  position: relative;
}

body .app-wallet-import-key-field input {
  padding-right: 2.75rem;
  font-family: var(--font-mono, monospace);
}

body .app-wallet-import-key-field button {
  position: absolute;
  top: 50%;
  right: 0.65rem;
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  transform: translateY(-50%);
  border: 0;
  border-radius: 999px;
  color: hsl(var(--muted-foreground));
  background: transparent;
}

body .app-wallet-import-key-field button:hover {
  color: hsl(var(--foreground));
  background: hsl(var(--muted));
}

body .app-wallet-import-error {
  margin: 0.4rem 0 0;
  color: hsl(var(--destructive));
  font-size: 0.75rem;
  line-height: 1.4;
}

/* Shipping audit polish: crisp light-mode product surface and calmer section rhythm. */
:root {
  --sm-graphite: #0a0f1a;
  --sm-soft-text: #4f5c6b;
  --sm-muted: #536171;
  --sm-page: #f5f7fb;
  --sm-paper: #ffffff;
  --sm-paper-2: #f8fbff;
  --sm-line: #dce3ee;
  --sm-line-strong: #c8d2e0;
  --sm-hairline: #dce3ee;
  --sm-cobalt: #0052ff;
  --sm-cobalt-2: #0646d8;
  --sm-forest: #15803d;
  --sm-blue: var(--sm-cobalt);
  --sm-blue-hover: var(--sm-cobalt-2);
  --sm-blue-soft: #eef4ff;
  --sm-blue-wash: #f6f9ff;
  --sm-green-soft: #ecfdf3;
  --sm-ink: var(--sm-graphite);
  --sm-lime: #ccff00;
}

.sm-home-rebuild,
.sm-home-rebuild main,
.sm-marketing-header + main {
  background: linear-gradient(180deg, #ffffff 0, #f8fbff 44rem, var(--sm-page) 100%) !important;
  color: var(--sm-graphite) !important;
}

.sm-home-rebuild :where(p, small, time) {
  color: var(--sm-soft-text);
}

.sm-marketing-header {
  border-bottom-color: rgb(10 15 26 / 8%) !important;
  background: #111111 !important;
  box-shadow: none !important;
}

.sm-marketing-nav {
  gap: clamp(18px, 2.4vw, 32px) !important;
}

.sm-marketing-nav a {
  position: relative;
  box-shadow: none !important;
  color: var(--sm-muted) !important;
}

.sm-marketing-nav a::after {
  content: "" !important;
  position: absolute;
  right: 0;
  bottom: -15px;
  left: 0;
  display: block !important;
  height: 2px !important;
  background: var(--sm-cobalt) !important;
  opacity: 0;
  transform: scaleX(0.55);
  transition:
    opacity 160ms ease,
    transform 160ms ease;
}

.sm-marketing-nav a[data-active="true"],
.sm-marketing-nav a:hover {
  background: transparent !important;
  color: var(--sm-cobalt) !important;
}

.sm-marketing-nav a[data-active="true"]::after,
.sm-marketing-nav a:hover::after {
  opacity: 1;
  transform: scaleX(1);
}

.sm-hero {
  border-bottom: 1px solid rgb(10 15 26 / 8%) !important;
  background:
    linear-gradient(90deg, rgb(0 82 255 / 3.2%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(0 82 255 / 3.2%) 1px, transparent 1px),
    linear-gradient(180deg, #ffffff 0%, #fbfdff 56%, #f4f8ff 100%) !important;
  background-size:
    104px 104px,
    104px 104px,
    100% 100%;
  padding: clamp(48px, 5.4vw, 78px) 0 clamp(42px, 4.6vw, 64px) !important;
}

.sm-hero::before {
  background:
    linear-gradient(90deg, #ffffff 0%, rgb(255 255 255 / 78%) 42%, rgb(255 255 255 / 0%) 82%),
    linear-gradient(180deg, rgb(255 255 255 / 0%) 70%, #f4f8ff 100%) !important;
  opacity: 0.95 !important;
}

.sm-hero-grid {
  width: min(100% - 56px, 1280px) !important;
  column-gap: clamp(40px, 5vw, 86px) !important;
  row-gap: clamp(22px, 3.2vw, 42px) !important;
  align-items: center !important;
}

.sm-hero-public .sm-hero-grid {
  grid-template-columns: minmax(420px, 0.9fr) minmax(520px, 1fr) !important;
}

.sm-hero-auth .sm-hero-grid {
  grid-template-columns: minmax(340px, 0.8fr) minmax(500px, 1fr) minmax(260px, 0.48fr) !important;
}

.sm-hero-intro {
  max-width: 600px !important;
  padding-top: 0 !important;
}

.sm-hero-eyebrow {
  color: var(--sm-forest) !important;
}

.sm-hero h1 {
  max-width: 590px !important;
  color: var(--sm-graphite) !important;
  font-size: clamp(3.5rem, 4.75vw, 5.65rem) !important;
  font-weight: 830 !important;
  line-height: 0.99 !important;
}

.sm-hero h1 span:last-child {
  color: var(--sm-cobalt) !important;
}

.sm-hero-intro > p:not(.sm-hero-eyebrow),
.sm-hero .sm-hero-intro > p:not(.sm-hero-eyebrow) {
  max-width: 535px !important;
  color: var(--sm-soft-text) !important;
  font-size: clamp(1rem, 1.05vw, 1.12rem) !important;
  line-height: 1.62 !important;
}

.sm-hero-actions {
  margin-top: 26px !important;
}

.sm-button-primary,
.sm-header-primary {
  box-shadow: 0 12px 28px rgb(0 82 255 / 18%) !important;
}

.sm-hero-trust-row {
  width: min(100%, 530px) !important;
  margin-top: 22px !important;
  border-top-color: rgb(10 15 26 / 12%) !important;
}

.sm-hero-trust-row span {
  color: #445064 !important;
}

.sm-hero-product-stage {
  min-height: auto !important;
}

.sm-hero-product-panel {
  width: min(100%, 610px) !important;
  border-color: rgb(10 15 26 / 12%) !important;
  background: #ffffff !important;
  padding: clamp(18px, 1.8vw, 24px) !important;
  box-shadow:
    0 1px 2px rgb(10 15 26 / 5%),
    0 24px 72px rgb(10 15 26 / 10%) !important;
}

.sm-product-panel-head h2 {
  color: var(--sm-graphite) !important;
}

.sm-product-market-grid article,
.sm-dashboard-card,
.sm-command-grid a,
.sm-setup-grid article,
.sm-thread-desk-checks article {
  border-color: rgb(10 15 26 / 10%) !important;
  background: #ffffff !important;
  box-shadow: 0 10px 32px rgb(10 15 26 / 5%) !important;
}

.sm-product-list p {
  color: var(--sm-soft-text) !important;
}

.sm-product-safe-row {
  border-color: rgb(0 82 255 / 16%) !important;
  background: var(--sm-blue-soft) !important;
  color: var(--sm-muted) !important;
}

.sm-home-metrics {
  gap: 12px !important;
  margin-top: 0 !important;
}

.sm-home-metrics div,
.sm-home-metrics div:first-child {
  min-height: 86px !important;
  min-width: 0 !important;
  grid-template-columns: minmax(0, 1fr) !important;
  row-gap: 4px !important;
  justify-items: center !important;
  text-align: center !important;
  border-color: rgb(10 15 26 / 10%) !important;
  background: #ffffff !important;
  padding: 12px !important;
  box-shadow: 0 10px 28px rgb(10 15 26 / 5%) !important;
  overflow: hidden !important;
}

.sm-home-metrics svg {
  grid-row: auto !important;
  width: 18px !important;
  height: 18px !important;
}

.sm-home-metrics strong {
  min-width: 0 !important;
  max-width: 100% !important;
  color: var(--sm-graphite) !important;
  font-size: clamp(0.9rem, 0.95vw, 1rem) !important;
  line-height: 1.05 !important;
  letter-spacing: 0 !important;
  white-space: nowrap !important;
  overflow-wrap: normal !important;
  word-break: normal !important;
}

.sm-home-metrics span {
  white-space: nowrap !important;
}

.sm-hero-feed-band::before {
  top: -14px !important;
  background: linear-gradient(90deg, transparent, rgb(0 82 255 / 18%), transparent) !important;
}

.sm-hero-feed {
  border-color: rgb(10 15 26 / 10%) !important;
  background: #ffffff !important;
  box-shadow:
    0 1px 2px rgb(10 15 26 / 4%),
    0 18px 46px rgb(10 15 26 / 7%) !important;
}

.sm-hero-feed-band .sm-hero-feed {
  background: #ffffff !important;
}

.sm-hero-feed-head {
  min-height: 54px !important;
}

.sm-hero-feed-tabs {
  height: 54px !important;
}

.sm-hero-feed-band .sm-feed-list,
.sm-hero-feed-band .sm-feed-state,
.sm-hero-feed-band .sm-feed-item {
  min-height: 112px !important;
}

.sm-feed-state,
.sm-feed-main p,
.sm-feed-side time {
  color: var(--sm-soft-text) !important;
}

.sm-thread-desk,
.sm-command-studio,
.sm-safety-rhythm {
  width: min(100% - 56px, 1220px) !important;
}

.sm-thread-desk {
  padding: clamp(72px, 7vw, 98px) 0 clamp(66px, 6vw, 92px) !important;
}

.sm-thread-desk::before {
  border-bottom-color: rgb(10 15 26 / 8%) !important;
  background: #ffffff !important;
}

.sm-thread-desk h2,
.sm-home-section-copy h2,
.sm-final-cta h2 {
  color: var(--sm-graphite) !important;
}

.sm-thread-desk-copy > p:last-child,
.sm-command-note p,
.sm-command-grid a p,
.sm-setup-grid p,
.sm-dashboard-card p {
  color: var(--sm-soft-text) !important;
}

.sm-thread-desk-visual {
  border-color: rgb(10 15 26 / 10%) !important;
  background: #ffffff !important;
  box-shadow: 0 18px 46px rgb(10 15 26 / 7%) !important;
}

.sm-home-dashboard {
  padding: clamp(64px, 7vw, 96px) 0 !important;
}

.sm-home-dashboard::before {
  border-bottom-color: rgb(10 15 26 / 8%) !important;
  background:
    linear-gradient(90deg, rgb(0 82 255 / 3%) 1px, transparent 1px),
    linear-gradient(180deg, #f8fbff 0%, #eef4ff 100%) !important;
  background-size:
    96px 96px,
    100% 100% !important;
}

.sm-dashboard-intro,
.sm-dashboard-grid {
  width: min(100% - 56px, 1220px) !important;
}

.sm-dashboard-card:nth-child(1),
.sm-dashboard-card:nth-child(3),
.sm-command-grid a[data-command-index],
.sm-safety-rhythm .sm-setup-grid article:nth-child(even) {
  transform: none !important;
}

.sm-command-studio {
  padding: clamp(70px, 7vw, 98px) 0 !important;
}

.sm-command-studio::before {
  border-bottom-color: rgb(10 15 26 / 8%) !important;
  background: #ffffff !important;
}

.sm-command-studio-layout {
  grid-template-columns: minmax(250px, 0.38fr) minmax(0, 1fr) !important;
  gap: clamp(24px, 4vw, 58px) !important;
  align-items: start !important;
}

.sm-command-note {
  border-left-color: var(--sm-cobalt) !important;
}

.sm-command-note strong,
.sm-command-grid strong,
.sm-setup-grid h3 {
  color: var(--sm-graphite) !important;
}

.sm-command-grid {
  gap: 16px !important;
}

.sm-command-grid a {
  min-height: 174px !important;
}

.sm-command-grid code {
  color: var(--sm-cobalt) !important;
}

.sm-safety-rhythm {
  padding: clamp(70px, 7vw, 96px) 0 !important;
}

.sm-safety-rhythm::before {
  background: #f8fbff !important;
}

.sm-safety-rhythm .sm-setup-grid {
  gap: 16px !important;
}

.sm-safety-rhythm .sm-setup-grid article {
  min-height: 188px !important;
}

.sm-final-cta {
  width: min(100% - 56px, 1220px) !important;
  margin-top: clamp(42px, 5vw, 66px) !important;
  border-color: rgb(255 255 255 / 18%) !important;
  background: linear-gradient(135deg, #0b1220 0%, #102a5f 66%, #0052ff 150%) !important;
  box-shadow: 0 26px 70px rgb(10 15 26 / 20%) !important;
}

.sm-final-cta h2 {
  color: #ffffff !important;
}

.sm-final-cta p,
.sm-final-cta small {
  color: rgb(255 255 255 / 76%) !important;
}

@media (max-width: 1240px) {
  .sm-hero-public .sm-hero-grid,
  .sm-hero-auth .sm-hero-grid {
    grid-template-columns: minmax(0, 1fr) !important;
  }

  .sm-hero-product-panel {
    margin-top: clamp(26px, 5vw, 56px) !important;
  }
}

@media (max-width: 980px) {
  .sm-thread-desk,
  .sm-command-studio,
  .sm-safety-rhythm,
  .sm-dashboard-grid,
  .sm-dashboard-intro,
  .sm-final-cta {
    width: min(100% - 44px, 760px) !important;
  }

  .sm-command-studio-layout {
    grid-template-columns: minmax(0, 1fr) !important;
  }

  .sm-command-note {
    position: relative !important;
    top: auto !important;
  }

  .sm-command-grid {
    grid-template-columns: minmax(0, 1fr) !important;
  }

  .sm-command-grid a,
  .sm-command-grid a[data-command-index] {
    grid-column: auto !important;
  }
}

@media (max-width: 640px) {
  .sm-marketing-header-inner,
  .sm-hero-mobile-intro,
  .sm-hero-grid,
  .sm-dashboard-grid,
  .sm-dashboard-intro,
  .sm-thread-desk,
  .sm-command-studio,
  .sm-safety-rhythm,
  .sm-final-cta {
    width: min(calc(100% - 28px), 430px) !important;
    max-width: calc(100vw - 28px) !important;
  }

  .sm-hero {
    padding: 30px 0 38px !important;
  }

  .sm-hero::before {
    background: linear-gradient(
      180deg,
      rgb(255 255 255 / 82%) 0%,
      rgb(255 255 255 / 24%) 58%,
      #f4f8ff 100%
    ) !important;
  }

  .sm-hero-mobile-intro {
    margin-bottom: 18px !important;
  }

  .sm-hero h1 {
    max-width: 336px !important;
    font-size: clamp(2.2rem, 9vw, 2.62rem) !important;
    line-height: 1.02 !important;
  }

  .sm-hero-intro > p:not(.sm-hero-eyebrow),
  .sm-hero .sm-hero-intro > p:not(.sm-hero-eyebrow) {
    width: min(100%, 326px) !important;
    max-width: 326px !important;
    font-size: 0.94rem !important;
    line-height: 1.55 !important;
  }

  .sm-hero-actions {
    width: min(100%, 294px) !important;
  }

  .sm-hero-trust-row {
    width: min(100%, 306px) !important;
    margin-top: 18px !important;
  }

  .sm-hero .sm-hero-grid {
    padding-top: 0 !important;
    row-gap: 14px !important;
  }

  .sm-hero .sm-hero-product-stage {
    margin-top: 10px !important;
  }

  .sm-hero-product-panel {
    margin-top: 0 !important;
    padding: 14px !important;
  }

  .sm-product-panel-head h2 {
    font-size: 1.65rem !important;
  }

  .sm-home-metrics {
    gap: 8px !important;
  }

  .sm-home-metrics div,
  .sm-home-metrics div:first-child {
    min-height: 78px !important;
    padding: 11px !important;
  }

  .sm-hero-feed-head {
    min-height: 50px !important;
  }

  .sm-hero-feed-tabs {
    height: auto !important;
  }

  .sm-hero-feed-band .sm-feed-list,
  .sm-hero-feed-band .sm-feed-state,
  .sm-hero-feed-band .sm-feed-item {
    min-height: 96px !important;
  }

  .sm-thread-desk,
  .sm-command-studio,
  .sm-safety-rhythm {
    padding-block: 48px !important;
  }

  .sm-home-dashboard {
    padding: 48px 0 !important;
  }

  .sm-thread-desk h2,
  .sm-home-section-copy h2,
  .sm-final-cta h2 {
    font-size: clamp(1.88rem, 7.6vw, 2.34rem) !important;
    line-height: 1.07 !important;
  }

  .sm-command-studio-layout {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 18px !important;
  }

  .sm-command-note {
    border-top: 1px solid rgb(0 82 255 / 18%) !important;
    border-left: 0 !important;
    padding: 16px 0 0 !important;
  }

  .sm-command-grid {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 10px !important;
  }

  .sm-command-grid a,
  .sm-command-grid a[data-command-index] {
    grid-column: auto !important;
    min-height: auto !important;
    padding: 16px !important;
  }

  .sm-safety-rhythm .sm-setup-grid article {
    min-height: auto !important;
  }

  .sm-final-cta {
    margin-top: 28px !important;
    padding: 38px 18px !important;
  }
}

/* Linkr custom surface pass: reply ledger, not template SaaS. */
:root {
  --lk-paper: #fbfaf5;
  --lk-paper-2: #f3f7ef;
  --lk-ink: #0c1016;
  --lk-muted: #596272;
  --lk-line: rgb(12 16 22 / 14%);
  --lk-line-strong: rgb(12 16 22 / 24%);
  --lk-blue: #0757ff;
  --lk-green: #178a45;
  --lk-amber: #c47a22;
  --lk-red: #c84444;
  --lk-shadow: 8px 8px 0 rgb(12 16 22 / 8%);
  --lk-radius: 8px;
}

body,
.sm-home,
.sm-app-shell {
  background:
    linear-gradient(90deg, rgb(12 16 22 / 4%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(12 16 22 / 3%) 1px, transparent 1px), var(--lk-paper) !important;
  background-size:
    28px 28px,
    28px 28px,
    100% 100% !important;
}

:where(.sm-home, .sm-app-content, .app-activity-console) h1,
:where(.sm-home, .sm-app-content, .app-activity-console) h2,
:where(.sm-home, .sm-app-content, .app-activity-console) h3,
:where(.sm-home, .sm-app-content, .app-activity-console) strong,
:where(.sm-home, .sm-app-content, .app-activity-console) b {
  letter-spacing: 0 !important;
}

.sm-marketing-header {
  border-bottom: 1px solid var(--lk-line-strong) !important;
  background: rgb(251 250 245 / 92%) !important;
  box-shadow: none !important;
  backdrop-filter: blur(14px);
}

.sm-marketing-header-inner {
  width: min(100% - 44px, 1360px) !important;
  min-height: 70px !important;
}

.sm-logo {
  gap: 10px !important;
}

.sm-logo img {
  width: 43px !important;
  height: 32px !important;
  border: 1px solid var(--lk-line-strong) !important;
  border-radius: 4px !important;
  background: var(--linkr-logo-bg, #9f8be7) !important;
  box-shadow: 3px 3px 0 rgb(23 138 69 / 20%) !important;
}

.sm-logo span {
  color: var(--lk-ink) !important;
  font-size: 1.24rem !important;
  font-weight: 880 !important;
}

.sm-marketing-nav {
  gap: 2px !important;
  border: 1px solid var(--lk-line) !important;
  border-radius: var(--lk-radius) !important;
  background: #ffffff !important;
  padding: 4px !important;
  box-shadow: none !important;
}

.sm-marketing-nav a {
  min-height: 36px !important;
  border-radius: 5px !important;
  padding: 0 12px !important;
  color: #2f3745 !important;
  font-size: 0.78rem !important;
  font-weight: 780 !important;
}

.sm-marketing-nav a[data-active="true"],
.sm-marketing-nav a:hover {
  background: var(--lk-ink) !important;
  color: #ffffff !important;
}

.sm-marketing-nav a::after {
  display: none !important;
}

.sm-header-primary,
.sm-header-secondary,
.sm-button {
  border-radius: 6px !important;
  box-shadow: none !important;
  font-weight: 820 !important;
}

.sm-header-primary,
.sm-button-primary {
  border: 1px solid var(--lk-ink) !important;
  background: var(--lk-ink) !important;
  color: #ffffff !important;
}

.sm-header-secondary,
.sm-button-secondary {
  border: 1px solid var(--lk-line-strong) !important;
  background: #ffffff !important;
  color: var(--lk-ink) !important;
}

.sm-header-primary:hover,
.sm-button-primary:hover {
  background: var(--lk-blue) !important;
  border-color: var(--lk-blue) !important;
}

.sm-hero {
  position: relative !important;
  border-bottom: 1px solid var(--lk-line-strong) !important;
