/* Linkr custom build pass: receipt rails, router panels, and flat product bands. */
:root {
  --lk-paper: #f4f7f3;
  --lk-paper-2: #eaf0e8;
  --lk-panel: #ffffff;
  --lk-ink: #0a0f16;
  --lk-muted: #536170;
  --lk-soft: #dfe7df;
  --lk-line: rgb(10 15 22 / 13%);
  --lk-line-strong: rgb(10 15 22 / 28%);
  --lk-blue: #0757ff;
  --lk-green: #078b4f;
  --lk-amber: #d88a21;
  --lk-red: #c23e3e;
  --lk-terminal: #0d141d;
  --lk-shadow: 9px 9px 0 rgb(10 15 22 / 10%);
  --lk-radius: 6px;
}

body,
.sm-home,
.sm-app-shell {
  background:
    linear-gradient(90deg, rgb(7 87 255 / 5%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(7 139 79 / 5%) 1px, transparent 1px), var(--lk-paper) !important;
  background-size:
    36px 36px,
    36px 36px,
    100% 100% !important;
  color: var(--lk-ink) !important;
}

.sm-home main,
.sm-marketing-header + main {
  background:
    radial-gradient(circle at 0 0, rgb(7 87 255 / 7%) 0 1px, transparent 1px), transparent !important;
  background-size: 18px 18px !important;
}

.sm-marketing-header {
  position: sticky !important;
  top: 0 !important;
  border-bottom: 1px solid var(--lk-line-strong) !important;
  background: rgb(244 247 243 / 94%) !important;
  box-shadow: none !important;
}

.sm-marketing-header::after {
  content: "" !important;
  position: absolute !important;
  right: 0 !important;
  bottom: -1px !important;
  left: 0 !important;
  height: 4px !important;
  background: linear-gradient(
    90deg,
    var(--lk-blue) 0 17%,
    transparent 17% 20%,
    var(--lk-green) 20% 53%,
    transparent 53% 56%,
    var(--lk-amber) 56% 100%
  ) !important;
  pointer-events: none !important;
}

.sm-marketing-header-inner {
  display: grid !important;
  width: min(100% - 48px, 1360px) !important;
  min-height: 72px !important;
  grid-template-columns: minmax(160px, 1fr) auto minmax(220px, 1fr) !important;
  gap: 18px !important;
}

.sm-logo {
  width: fit-content !important;
  gap: 9px !important;
  border: 1px solid var(--lk-line-strong) !important;
  border-radius: var(--lk-radius) !important;
  background: var(--lk-panel) !important;
  padding: 6px 10px 6px 7px !important;
  color: var(--lk-ink) !important;
  box-shadow: 4px 4px 0 rgb(7 139 79 / 15%) !important;
}

.sm-logo img {
  width: 36px !important;
  height: 28px !important;
  border: 1px solid var(--lk-line-strong) !important;
  border-radius: 4px !important;
  background: var(--linkr-logo-bg, #9f8be7) !important;
  box-shadow: none !important;
}

.sm-logo span {
  color: var(--lk-ink) !important;
  font-size: 1.13rem !important;
  font-weight: 900 !important;
}

.sm-marketing-nav {
  display: grid !important;
  grid-auto-flow: column !important;
