/* Linkr clean pass: fewer effects, stronger spacing, product-specific without ornament. */
:root {
  --wc-bg: #f6f7f8;
  --wc-surface: #ffffff;
  --wc-surface-soft: #f9fafb;
  --wc-ink: #111827;
  --wc-muted: #667085;
  --wc-faint: #98a2b3;
  --wc-line: #e4e7ec;
  --wc-line-strong: #d0d5dd;
  --wc-blue: #175cff;
  --wc-green: #0f8b5f;
  --wc-dark: #101828;
  --wc-radius: 8px;
  --wc-shadow: 0 1px 2px rgb(16 24 40 / 5%);
}

html,
body {
  background: var(--wc-bg) !important;
}

body,
.sm-home,
.sm-app-shell,
.sm-marketing-header + main,
.sm-home main {
  background: var(--wc-bg) !important;
  color: var(--wc-ink) !important;
}

:where(.sm-home, .sm-app-content, .app-activity-console, .app-live-page) h1,
:where(.sm-home, .sm-app-content, .app-activity-console, .app-live-page) h2,
:where(.sm-home, .sm-app-content, .app-activity-console, .app-live-page) h3,
:where(.sm-home, .sm-app-content, .app-activity-console, .app-live-page) strong,
:where(.sm-home, .sm-app-content, .app-activity-console, .app-live-page) b {
  letter-spacing: 0 !important;
}

.sm-marketing-header {
  border-bottom: 1px solid var(--wc-line) !important;
  background: rgb(255 255 255 / 92%) !important;
  box-shadow: none !important;
  backdrop-filter: blur(16px) !important;
}

.sm-marketing-header::after,
.sm-hero::before,
.sm-hero::after,
.sm-hero-product-stage::before,
.sm-hero-product-panel::before,
.sm-dashboard-card::before,
.sm-app-content .sm-card::before,
.app-live-hero::before,
.app-activity-console::before,
.sm-command-grid a::before,
.sm-command-grid a::after,
.sm-setup-grid article::after,
.sm-app-sidebar::after {
  display: none !important;
  content: none !important;
}

.sm-marketing-header-inner {
  width: min(100% - 48px, 1200px) !important;
  min-height: 72px !important;
  grid-template-columns: minmax(140px, 1fr) auto minmax(220px, 1fr) !important;
  gap: 20px !important;
}

.sm-logo {
  gap: 10px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  padding: 0 !important;
  box-shadow: none !important;
}

.sm-logo img {
  width: 38px !important;
  height: 30px !important;
  border: 1px solid var(--wc-line-strong) !important;
  border-radius: 6px !important;
  background: var(--linkr-logo-bg, #9f8be7) !important;
}

.sm-logo span {
  color: var(--wc-ink) !important;
  font-size: 1.14rem !important;
  font-weight: 850 !important;
}

.sm-marketing-nav {
  gap: 2px !important;
  border: 1px solid var(--wc-line) !important;
  border-radius: var(--wc-radius) !important;
  background: var(--wc-surface-soft) !important;
  padding: 3px !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.sm-marketing-nav a {
  min-height: 36px !important;
  border: 0 !important;
  border-radius: 6px !important;
  padding: 0 12px !important;
  color: #344054 !important;
  font-size: 0.76rem !important;
  font-weight: 750 !important;
  text-transform: none !important;
