/* Rayo clone pass: full template visual system adapted for Linkr content. */
:root {
  --rayo-base: #111111;
  --rayo-base-rgb: 14 14 22;
  --rayo-tint: #1c1c1c;
  --rayo-shade: #0a0a0a;
  --rayo-opp: #faf7f6;
  --rayo-accent: #ccff00;
  --rayo-additional: #9f8be7;
  --rayo-muted: #838383;
  --rayo-muted-extra: #535151;
  --rayo-line: rgb(255 255 255 / 10%);
  --rayo-line-strong: rgb(255 255 255 / 18%);
  --rayo-radius-s: 1rem;
  --rayo-radius-m: 2.6rem;
  --rayo-radius-l: 5rem;
  --rayo-radius-xl: 8rem;
  --rayo-font: "Funnel Sans", var(--font-sans);
  --rayo-display: "Funnel Display", var(--font-display);
  --rayo-ease: cubic-bezier(0.23, 0.65, 0.74, 1.09);
}

html {
  scroll-padding-top: 120px;
}

body,
.sm-home,
.sm-home-rebuild,
.sm-home-rebuild main,
.sm-marketing-header + main,
.sm-app-shell {
  background: var(--rayo-base) !important;
  color: var(--rayo-opp) !important;
  font-family: var(--rayo-font) !important;
}

body {
  overflow-x: clip !important;
}

:where(.sm-home, .sm-app-shell, .sm-auth-page, .app-activity-console)
  :where(h1, h2, h3, h4, strong, b),
.sm-logo {
  font-family: var(--rayo-display) !important;
  letter-spacing: 0 !important;
}

:where(.sm-home, .sm-app-shell, .sm-auth-page, .app-activity-console)
  :where(p, small, time, span, a, button, input, select, textarea, code) {
  font-family: var(--rayo-font) !important;
}

.sm-rayo-loader {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  gap: 22px;
  background: var(--rayo-base);
  color: var(--rayo-opp);
  transition:
    opacity 480ms ease,
    visibility 480ms ease;
  animation: sm-rayo-loader-exit 480ms ease 1350ms forwards;
}

.sm-rayo-loader[data-loaded="true"] {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.sm-rayo-loader__mark {
  display: grid;
  width: 86px;
  height: 86px;
  place-items: center;
  border-radius: 999px;
  background: var(--rayo-opp);
}

.sm-rayo-loader__mark img {
