    font-size: 1.85rem !important;
  }

  .sm-thread-desk {
    padding: 76px 0 70px !important;
  }

  .sm-thread-desk h2,
  .sm-dashboard-intro h2,
  .sm-home-section-copy h2,
  .sm-final-cta h2,
  .app-live-hero h1 {
    font-size: 2.65rem !important;
  }

  .sm-thread-desk-visual {
    min-height: 280px !important;
    border-radius: 32px !important;
  }

  .sm-rayo-word-marquee span {
    font-size: 4rem;
  }

  .sm-rayo-word-marquee i {
    width: 36px;
    height: 36px;
  }

  .sm-home-dashboard {
    padding: 76px 0 !important;
  }

  .sm-home-dashboard::before {
    border-radius: 42px 42px 0 0 !important;
  }

  .sm-command-studio {
    padding: 78px 0 !important;
  }

  .sm-command-studio-layout {
    gap: 24px !important;
  }

  .sm-command-note {
    position: relative !important;
    top: auto !important;
  }

  .sm-command-grid a {
    min-height: 260px !important;
  }

  .sm-safety-rhythm .sm-setup-grid article {
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 12px !important;
    padding: 26px 0 !important;
  }

  .sm-rayo-media-line figure,
  .sm-rayo-media-line strong {
    width: 230px;
    height: 196px;
    border-radius: 28px;
  }

  .sm-rayo-media-line strong {
    font-size: 1.8rem;
  }

  .sm-final-cta {
    min-height: 430px !important;
    border-radius: 42px !important;
    padding: 36px 18px !important;
  }

  .sm-final-cta::before {
    width: 140px !important;
    height: 140px !important;
    opacity: 0.45 !important;
  }

  .sm-rayo-footer div {
    font-size: 7.8rem;
  }

  .sm-app-content {
    width: calc(100% - 28px) !important;
    padding-block: 30px !important;
  }

  .app-live-hero,
  .sm-marketing-header + main .app-live-hero {
    min-height: 260px !important;
    padding: 28px !important;
