  }
}

@media (prefers-reduced-motion: reduce) {
  .sm-rayo-loader__bar span,
  .sm-rayo-object,
  .sm-rayo-title-marquee div,
  .sm-rayo-rotating svg,
  .sm-rayo-word-marquee div,
  .sm-rayo-media-line {
    animation: none !important;
  }
}

body {
  background: var(--sm-black);
  color: var(--sm-cream);
}

body :where(.rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl, .rounded-full) {
  border-radius: 0 !important;
}

body :where(button, a, input, textarea, select) {
  outline-color: var(--sm-lime);
}

body :where(button, a) {
  transition:
    background-color 160ms ease,
    color 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

body :where(button, a):focus-visible,
body :where(input, textarea, select):focus-visible {
  outline: 2px solid var(--sm-lime);
  outline-offset: 3px;
}

body :where(input, textarea, select) {
  border: 2px solid var(--sm-line) !important;
  background: var(--sm-panel) !important;
  color: var(--sm-cream) !important;
}

body :where(input, textarea, select)::placeholder {
  color: rgb(167 163 151 / 72%);
}

body .text-muted-foreground {
  color: var(--sm-muted) !important;
}

body .text-primary {
  color: var(--sm-lime) !important;
}

body .bg-primary {
  background: var(--sm-lime) !important;
}

body .border-border,
body .border-input {
  border-color: var(--sm-line) !important;
}

body .bg-background,
body .bg-surface,
body .bg-muted {
  background: var(--sm-black) !important;
}

body .bg-surface\/60,
body .bg-surface-elevated\/60,
body .bg-muted\/60 {
  background: var(--sm-panel) !important;
}

body .sm-card {
  border: 2px solid #f9f1da10 !important;
  background: var(--sm-panel) !important;
  color: var(--sm-cream) !important;
}

body .sm-mono,
body code {
  color: var(--sm-lime);
  font-size: 0.92em;
}

body .capitalize {
  text-transform: none;
}

body
  :where(
    .sm-header-secondary,
    .sm-header-primary,
    .sm-button,
    .app-live-link,
    .sm-app-content button,
    .sm-auth-page button,
    .sm-app-user button
  ) {
  border-radius: var(--sm-radius) !important;
}

body
  :where(
    .sm-card,
    .sm-hero-command-panel,
    .sm-x-machine,
    .sm-reply-chip,
    .sm-reply-engine,
    .sm-action-lanes li,
    .sm-engine-output,
    .sm-command-board,
    .sm-setup-console,
    .sm-rule-stack,
    .sm-app-content header,
    .sm-app-content .app-live-hero,
    .sm-marketing-header + main > header,
    .sm-marketing-header + main .app-live-hero,
    .app-launch-feature,
    .app-launch-tape,
    .app-activity-console,
    .app-live-stats,
    .sm-command-ledger
  ) {
  border-radius: var(--sm-radius) !important;
}

body
  :where(
    .sm-pixel-label,
    .sm-hero-command-live > strong,
    .sm-hero-flow-list li > span,
    .sm-stage-ribbon,
    .sm-x-machine-top > span,
    .sm-x-avatar,
    .sm-reply-chip strong,
    .sm-action-lanes li > span,
    .sm-engine-output strong,
    .sm-command-picker button span,
    .sm-command-output > span,
    .sm-command-output code,
    .app-live-kicker,
    .app-live-signal,
    .app-launch-art,
    .app-status,
    .app-activity-kind,
    .app-activity-row pre,
    .sm-app-user img,
    .sm-app-user > span
  ) {
  border-radius: var(--sm-radius-sm) !important;
}

body
  :where(
    .sm-hero-command-panel,
    .sm-x-machine,
    .sm-reply-chip,
    .sm-reply-engine,
    .sm-action-lanes li,
    .sm-engine-output,
    .sm-command-board,
    .sm-setup-console,
    .sm-rule-stack,
    .app-launch-feature,
    .app-launch-tape,
    .app-activity-console,
    .app-live-stats,
    .sm-command-ledger,
    .app-launch-art
  ) {
  overflow: hidden;
}

.sm-stage-ribbon {
  border-radius: var(--sm-radius-sm) var(--sm-radius-sm) 0 0 !important;
}

/* Shared logo and marketing header */
.sm-logo {
  display: inline-flex;
  align-items: center;
  color: var(--sm-cream);
}

.sm-logo img {
  display: block;
  width: clamp(3rem, 4vw, 4.25rem);
  height: clamp(3rem, 4vw, 4.25rem);
  object-fit: contain;
}

.sm-marketing-header .sm-logo {
  background: var(--linkr-logo-bg, #9f8be7);
  padding-right: 10px;
  padding-left: 10px;
  padding-top: 2px;
  padding-bottom: 2px;
}

.sm-marketing-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--sm-hero-header-bg);
}

.sm-marketing-header-inner {
  display: grid;
  width: min(100% - 2rem, 1500px);
  min-height: 4.25rem;
  margin-inline: auto;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 1.4rem;
  align-items: center;
}

.sm-marketing-nav {
  display: flex;
  justify-content: center;
  gap: clamp(0.75rem, 2vw, 2.1rem);
  color: var(--sm-cream);
  font-family: var(--font-display);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.sm-marketing-nav a:hover {
  color: var(--sm-lime);
}

.sm-header-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.sm-header-secondary,
.sm-header-primary,
.sm-button {
  display: inline-flex;
  min-height: 3.05rem;
  align-items: center;
  justify-content: center;
  border: 2px solid #f9f1da10;
  padding-inline: 1.25rem;
  color: var(--sm-cream);
  font-family: var(--font-display);
  font-size: 0.86rem;
  font-weight: 800;
  text-transform: none;
}

.sm-header-primary,
.sm-button-primary {
  border-color: var(--sm-lime);
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-header-secondary:hover,
.sm-button-secondary:hover {
  border-color: var(--sm-lime);
  color: var(--sm-lime);
}

.sm-header-primary:hover,
.sm-button-primary:hover {
  transform: translateY(-2px);
}

/* Landing page */
.sm-home-rebuild {
  min-height: 100vh;
  overflow: hidden;
  background: var(--sm-black);
  color: var(--sm-cream);
}

.sm-page {
  width: min(100% - clamp(1rem, 3vw, 3rem), 1500px);
  margin-inline: auto;
}

.sm-pixel-label {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  border: 2px solid var(--sm-lime);
  background: var(--sm-lime);
  padding: 0.38rem 0.58rem;
  color: var(--sm-black);
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
}

.sm-hero {
  --hero-timeline-progress: 0;
  --hero-timeline-x: 0px;
  --hero-timeline-y: 0px;
  --hero-timeline-tilt: 0deg;
  --hero-timeline-scale: 1;
  --hero-timeline-opacity: 1;
  position: relative;
  display: grid;
  min-height: calc(100vh - 8.45rem);
  min-height: calc(100svh - 8.45rem);
  align-items: stretch;
  background: var(--sm-hero-header-bg);
  overflow: hidden;
}

.sm-hero::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: clamp(0.5rem, 1.7vw, 1.25rem);
  background: var(--sm-lime);
}

.sm-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.14fr) minmax(20rem, 0.86fr);
  gap: clamp(1rem, 2.8vw, 2.5rem);
  align-items: center;
  min-height: inherit;
  padding-block: clamp(0.6rem, 1.4vw, 1.25rem);
}

.sm-hero-copy {
  display: grid;
  align-content: center;
  max-width: 56rem;
  padding-left: clamp(0.4rem, 2vw, 1.25rem);
}

.sm-hero h1 {
  margin-top: 0.75rem;
  color: var(--sm-cream);
  font-family: var(--font-display);
  font-size: clamp(3.15rem, 5.95vw, 6.45rem);
  font-weight: 900;
  line-height: 0.92;
  text-transform: uppercase;
}

.sm-hero h1 span {
  display: block;
}

.sm-hero h1 span:last-child {
  color: var(--sm-lime);
}

.sm-hero-copy > p:not(.sm-pixel-label) {
  max-width: 38rem;
  margin-top: 0.9rem;
  color: var(--sm-muted);
  font-size: clamp(1.02rem, 1.25vw, 1.18rem);
  font-weight: 500;
  line-height: 1.55;
}

.sm-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin-top: 1.25rem;
}

.sm-hero-command-panel {
  display: grid;
  width: min(100%, 38rem);
  margin-top: 1.25rem;
  border: 2px solid #f9f1da10;
  background: #090a08;
  overflow: hidden;
}

.sm-hero-command-live {
  display: grid;
  min-height: 4rem;
  grid-template-columns: 4rem minmax(0, 1fr) auto;
  align-items: stretch;
  border-bottom: 2px solid #f9f1da10;
  background: #000;
}

.sm-hero-command-live img {
  width: 4rem;
  height: 4rem;
  border-right: 2px solid #f9f1da10;
  object-fit: cover;
  object-position: center;
}

.sm-hero-command-live div {
  display: grid;
  min-width: 0;
  align-content: center;
  gap: 0.18rem;
  padding: 0.55rem 0.75rem;
}

.sm-hero-command-live span {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  color: var(--sm-lime);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
}

.sm-hero-command-live span::before {
  content: "";
  width: 0.58rem;
  height: 0.58rem;
  background: var(--sm-lime);
  animation: sm-router-tick 1.4s ease-in-out infinite;
}

.sm-hero-command-live code {
  display: block;
  color: var(--sm-cream);
  font-size: clamp(0.82rem, 1.1vw, 0.95rem);
  font-weight: 700;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.sm-hero-command-live > strong {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-left: 2px solid #f9f1da10;
  background: var(--sm-lime);
  padding-inline: 0.72rem;
  color: var(--sm-black);
  font-size: 0.74rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-hero-flow-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
}

.sm-hero-flow-list li {
  display: grid;
  min-width: 0;
  min-height: 4.45rem;
  grid-template-columns: 2.15rem minmax(0, 1fr);
  gap: 0.58rem;
  align-items: center;
  border-left: 2px solid #f9f1da10;
  padding: 0.68rem;
}

.sm-hero-flow-list li:first-child {
  border-left: 0;
}

.sm-hero-flow-list li > span {
  display: grid;
  width: 2.15rem;
  height: 2.15rem;
  place-items: center;
  border: 2px solid #f9f1da10;
  color: var(--sm-lime);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
}

.sm-hero-flow-list strong,
.sm-hero-flow-list p {
  display: block;
}

.sm-hero-flow-list strong {
  color: var(--sm-cream);
  font-size: 0.82rem;
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
}

.sm-hero-flow-list p {
  margin-top: 0.22rem;
  color: var(--sm-muted);
  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.25;
}

.sm-hero-stage {
  position: relative;
  display: grid;
  align-items: center;
  justify-items: stretch;
  min-width: 0;
  opacity: var(--hero-timeline-opacity);
  transform: translate3d(var(--hero-timeline-x), var(--hero-timeline-y), 0)
    rotate(var(--hero-timeline-tilt)) scale(var(--hero-timeline-scale));
  transform-origin: 88% 38%;
  will-change: opacity, transform;
}

.sm-stage-ribbon {
  position: absolute;
  top: -1.9rem;
  left: 0;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 0;
  border: 2px solid var(--sm-lime);
  border-bottom: 0;
  background: var(--sm-lime);
  padding: 0;
  color: var(--sm-black);
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
  transform: none;
}

.sm-stage-ribbon span,
.sm-stage-ribbon strong {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  line-height: 1;
  padding-inline: 0.8rem;
  padding-top: 0.08rem;
}

.sm-stage-ribbon strong {
  border-left: 2px solid var(--sm-lime);
  background: #080907;
  color: var(--sm-cream);
}

.sm-x-machine {
  position: relative;
  display: grid;
  width: min(100%, 43rem);
  margin-left: auto;
  border: 2px solid var(--sm-lime);
  background: #050605;
  color: #f9f1da;
  transform: none;
  animation: sm-machine-settle 680ms cubic-bezier(0.2, 0.9, 0.2, 1) both;
}

.sm-x-machine-top {
  display: grid;
  grid-template-columns: 2.5rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.8rem;
  border-bottom: 2px solid rgba(249, 241, 218, 0.068);
  padding: 0.95rem 1rem;
}

.sm-x-machine-top > span {
  display: grid;
  width: 2.2rem;
  height: 2.2rem;
  place-items: center;
  background: var(--sm-cream);
  color: #000;
  font-weight: 800;
}

.sm-x-machine-top strong,
.sm-x-machine-top small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sm-x-machine-top strong {
  font-size: 1.02rem;
  font-weight: 800;
}

.sm-x-machine-top small {
  color: var(--sm-muted);
  font-size: 0.78rem;
  font-weight: 700;
}

.sm-x-post,
.sm-x-reply {
  display: grid;
  grid-template-columns: 2.7rem minmax(0, 1fr);
  gap: 0.8rem;
  border-bottom: 2px solid rgb(249 241 218 / 12%);
  padding: 1rem;
}

.sm-x-avatar {
  display: grid;
  width: 2.6rem;
  height: 2.6rem;
  place-items: center;
  border: 2px solid var(--sm-cream);
  background: var(--sm-panel);
  color: var(--sm-lime);
  font-size: 0.78rem;
  font-weight: 800;
}

.sm-x-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  margin-bottom: 0.42rem;
  color: var(--sm-muted);
  font-size: 0.84rem;
  font-weight: 700;
}

.sm-x-meta strong {
  color: var(--sm-cream);
}

.sm-x-post p,
.sm-x-bot-reply p {
  margin-top: 0.22rem;
  color: var(--sm-cream);
  font-size: 1rem;
  line-height: 1.42;
}

.sm-x-user-reply {
  background: #111;
}

.sm-x-user-reply span,
.sm-x-bot-reply span {
  display: block;
  margin-bottom: 0.35rem;
  color: var(--sm-muted);
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-x-user-reply code {
  color: var(--sm-lime);
  font-size: clamp(0.9rem, 1.6vw, 1.08rem);
  font-weight: 700;
  line-height: 1.35;
  white-space: normal;
}

.sm-x-router {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.45rem;
  border-bottom: none;
  padding: 0.7rem 1rem;
}

.sm-x-router span {
  height: 0.6rem;
  border: 2px solid #f9f1da10;
  background: var(--sm-panel);
  animation: sm-router-tick 1.8s ease-in-out infinite;
}

.sm-x-router span:nth-child(2) {
  animation-delay: 0.2s;
}

.sm-x-router span:nth-child(3) {
  animation-delay: 0.4s;
}

.sm-x-bot-reply {
  border-bottom: 0;
  background: #070707;
}

.sm-x-bot-reply .sm-x-avatar {
  background: var(--sm-lime);
  color: #000;
}

.sm-x-command-tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 2px solid rgb(249 241 218 / 14%);
}

.sm-x-command-tabs button {
  min-width: 0;
  border: 0;
  border-left: 2px solid rgb(249 241 218 / 14%);
  background: #000;
  padding: 0.78rem 0.35rem;
  color: var(--sm-muted);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-x-command-tabs button:first-child {
  border-left: 0;
}

.sm-x-command-tabs button[data-active="true"],
.sm-x-command-tabs button:hover {
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-command-tape {
  overflow: hidden;
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-tape-track {
  display: flex;
  width: max-content;
  animation: sm-tape-roll 28s linear infinite;
}

.sm-tape-track span {
  display: inline-flex;
  min-height: 4.2rem;
  align-items: center;
  border-left: 2px solid var(--sm-black);
  padding-inline: clamp(1.2rem, 3vw, 3rem);
  font-family: var(--font-mono);
  font-size: clamp(0.82rem, 1.4vw, 1rem);
  font-weight: 800;
  white-space: nowrap;
}

.sm-block {
  padding-block: clamp(4rem, 8vw, 8rem);
}

.sm-section-head {
  display: grid;
  max-width: 55rem;
  gap: 1rem;
}

.sm-section-head-wide {
  max-width: 75rem;
}

.sm-section-head h2,
.sm-final-cta h2 {
  color: var(--sm-cream);
  font-size: clamp(3rem, 7vw, 6.8rem);
  font-weight: 800;
  line-height: 0.86;
  text-transform: uppercase;
}

.sm-section-head p:not(.sm-pixel-label),
.sm-final-cta p:not(.sm-pixel-label) {
  max-width: 42rem;
  color: var(--sm-muted);
  font-size: clamp(1rem, 1.45vw, 1.18rem);
  font-weight: 600;
  line-height: 1.55;
}

.sm-steps {
  --steps-progress: 1;
  --steps-lift: 0px;
  --steps-lift-small: 0px;
  --steps-fade: 1;
  --steps-bar-scale: 1;
  --steps-lane-shift: 0px;
  --steps-lane-shift-neg: 0px;
  position: relative;
  overflow: hidden;
  border-bottom: 0;
  background: var(--sm-panel);
  isolation: isolate;
  padding-block: clamp(4rem, 7vw, 7rem);
}

.sm-steps::before {
  content: "";
  position: absolute;
  inset: 0 0 0 auto;
  width: clamp(0.65rem, 1.4vw, 1.15rem);
  background: var(--sm-lime);
  opacity: var(--steps-fade);
}

.sm-steps-stage {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(18rem, 0.85fr) minmax(31rem, 1.15fr);
  gap: clamp(2rem, 5vw, 5rem);
  align-items: center;
}

.sm-steps-copy {
  display: grid;
  max-width: 48rem;
  gap: 0.9rem;
  opacity: var(--steps-fade);
  transform: translate3d(0, var(--steps-lift), 0);
  will-change: opacity, transform;
}

.sm-steps-copy h2 {
  color: var(--sm-cream);
  font-size: clamp(2.8rem, 5.2vw, 5.8rem);
  font-weight: 800;
  line-height: 0.84;
  text-transform: uppercase;
}

.sm-steps-copy > p:not(.sm-pixel-label) {
  max-width: 42rem;
  color: var(--sm-muted);
  font-size: clamp(1rem, 1.45vw, 1.18rem);
  font-weight: 600;
  line-height: 1.55;
}

.sm-reply-chip {
  display: grid;
  width: min(100%, 42rem);
  grid-template-columns: minmax(0, 1fr) auto;
  border: 2px solid var(--sm-lime);
  background: var(--sm-black);
  color: var(--sm-cream);
  font-family: var(--font-mono);
  font-size: clamp(0.78rem, 1.2vw, 0.98rem);
  font-weight: 800;
  transform: translate3d(var(--steps-lane-shift-neg), 0, 0);
  will-change: transform;
}

.sm-reply-chip span,
.sm-reply-chip strong {
  display: inline-flex;
  min-height: 2.65rem;
  align-items: center;
  padding-inline: 0.9rem;
}

.sm-reply-chip strong {
  border-left: 2px solid var(--sm-lime);
  background: var(--sm-lime);
  color: var(--sm-black);
  text-transform: uppercase;
}

.sm-reply-engine {
  position: relative;
  display: grid;
  min-height: clamp(27rem, 38vw, 34rem);
  grid-template-columns: minmax(12rem, 0.62fr) minmax(20rem, 1fr);
  grid-template-rows: minmax(0, 1fr) auto;
  gap: clamp(0.9rem, 1.8vw, 1.25rem);
  align-items: center;
  border: 0px;
  background: var(--sm-black);
  padding: clamp(0.9rem, 1.8vw, 1.5rem);
  opacity: var(--steps-fade);
  transform: translate3d(0, var(--steps-lift-small), 0);
  will-change: opacity, transform;
  box-shadow: 0 0 3.8rem #ccff001f;
}

.sm-reply-engine::after {
  content: "";
  position: absolute;
  inset: -0.9rem 1rem auto auto;
  width: min(36%, 14rem);
  height: 0.9rem;
  background: var(--sm-lime);
  transform: scaleX(var(--steps-bar-scale));
  transform-origin: right center;
}

.sm-engine-core {
  position: relative;
  z-index: 1;
  display: grid;
  aspect-ratio: 1;
  min-height: 12.5rem;
  place-items: center;
  align-content: center;
  align-self: center;
  gap: 0.35rem;
  border: 3px solid var(--sm-black);
  background: var(--sm-lime);
  color: var(--sm-black);
  clip-path: polygon(7% 0, 100% 0, 100% 86%, 90% 100%, 0 100%, 0 14%);
  padding: clamp(1rem, 1.8vw, 1.25rem);
  text-align: center;
  text-transform: uppercase;
}

.sm-engine-core span,
.sm-engine-core small {
  font-family: var(--font-mono);
  font-size: clamp(0.66rem, 1vw, 0.82rem);
  font-weight: 800;
}

.sm-engine-core strong {
  max-width: 100%;
  font-size: clamp(1.05rem, 2.25vw, 1.85rem);
  font-weight: 800;
  line-height: 0.95;
  overflow-wrap: anywhere;
}

.sm-engine-core small {
  max-width: 8rem;
  line-height: 1.25;
}

.sm-action-lanes {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 0.72rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sm-action-lanes li {
  position: relative;
  display: grid;
  min-height: clamp(4.35rem, 5.3vw, 5rem);
  grid-template-columns: 4.15rem minmax(0, 1fr);
  border: 2px solid #f9f1da10;
  background: var(--sm-panel);
  opacity: var(--steps-fade);
  overflow: hidden;
  will-change: opacity, transform;
}

.sm-action-lanes li::after {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 0.32rem;
  background: var(--sm-lime);
  transform: scaleY(var(--steps-bar-scale));
  transform-origin: bottom center;
}

.sm-action-lanes li:nth-child(odd) {
  transform: translate3d(var(--steps-lane-shift), 0, 0);
}

.sm-action-lanes li:nth-child(even) {
  transform: translate3d(var(--steps-lane-shift-neg), 0, 0);
}

.sm-action-lanes li:nth-child(2) {
  background: var(--sm-panel-2);
}

.sm-action-lanes li:nth-child(3) {
  border-color: var(--sm-lime);
}

.sm-action-lanes li > span {
  display: grid;
  place-items: center;
  border-right: 2px solid #f9f1da10;
  color: var(--sm-lime);
  font-family: var(--font-mono);
  font-size: clamp(1rem, 2vw, 1.5rem);
  font-weight: 800;
}

.sm-action-lanes li > div {
  display: grid;
  gap: 0.22rem;
  align-content: center;
  padding: clamp(0.68rem, 1.2vw, 0.92rem);
}

.sm-action-lanes h3 {
  color: var(--sm-cream);
  font-size: clamp(0.92rem, 1.35vw, 1.18rem);
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
}

.sm-action-lanes p {
  color: var(--sm-muted);
  font-size: 0.82rem;
  font-weight: 600;
  line-height: 1.32;
}

.sm-engine-output {
  position: relative;
  z-index: 1;
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1fr) auto;
  border: 3px solid var(--sm-black);
  background: var(--sm-lime);
  color: var(--sm-black);
  transform: translate3d(0, var(--steps-lift-small), 0);
  will-change: transform;
}

.sm-engine-output span,
.sm-engine-output strong {
  display: inline-flex;
  min-height: 3.45rem;
  align-items: center;
  padding-inline: clamp(1rem, 2vw, 1.5rem);
  font-weight: 800;
  text-transform: uppercase;
}

.sm-engine-output span {
  font-family: var(--font-mono);
  font-size: 0.8rem;
}

.sm-engine-output strong {
  border-left: 3px solid var(--sm-black);
  font-size: clamp(1.2rem, 2.6vw, 2.2rem);
  line-height: 0.9;
}

.sm-command-lab {
  position: relative;
  overflow: hidden;
  background: var(--sm-black);
}

.sm-command-lab::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: clamp(0.65rem, 1.4vw, 1.15rem);
  background: var(--sm-lime);
}

.sm-command-lab-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(19rem, 0.92fr) minmax(30rem, 1.08fr);
  gap: clamp(2rem, 4.5vw, 4.5rem);
  align-items: center;
}

.sm-command-lab .sm-section-head {
  max-width: 46rem;
  min-width: 0;
}

.sm-command-board {
  position: relative;
  display: grid;
  width: min(100%, 52rem);
  min-height: clamp(25rem, 35vw, 32rem);
  grid-template-columns: minmax(9.6rem, 0.35fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  justify-self: end;
  border: 0px;
  background: var(--sm-panel);
  overflow: hidden;
  box-shadow: 0 0 3.8rem #ccff001f;
}

.sm-command-board::before {
  content: "Reply / read / check / act";
  display: flex;
  grid-column: 1 / -1;
  min-height: 3.1rem;
  align-items: center;
  border-bottom: 2px solid #f9f1da10;
  background: var(--sm-lime);
  padding-inline: 1rem;
  color: var(--sm-black);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-command-picker {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: repeat(5, minmax(0, 1fr));
  border-right: 2px solid #f9f1da10;
}

.sm-command-picker button {
  display: grid;
  min-width: 0;
  min-height: 4.2rem;
  grid-template-columns: 2.1rem minmax(0, 1fr);
  gap: 0.7rem;
  align-items: center;
  border: 0;
  border-top: 2px solid #f9f1da10;
  background: var(--sm-panel);
  padding: 0.85rem;
  color: var(--sm-muted);
  cursor: pointer;
  font-size: clamp(0.78rem, 0.85vw, 0.92rem);
  font-weight: 800;
  line-height: 1;
  text-align: left;
  text-transform: uppercase;
}

.sm-command-picker button:first-child {
  border-top: 0;
}

.sm-command-picker button span {
  display: grid;
  width: 2.1rem;
  height: 2.1rem;
  place-items: center;
  border: 2px solid #f9f1da10;
  color: var(--sm-lime);
  font-family: var(--font-mono);
  font-size: 0.72rem;
}

.sm-command-picker button[data-active="true"],
.sm-command-picker button:hover {
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-command-picker button[data-active="true"] span,
.sm-command-picker button:hover span {
  border-color: var(--sm-black);
  color: var(--sm-black);
}

.sm-command-output {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-rows: auto auto auto auto minmax(min-content, 1fr);
  align-content: stretch;
  gap: clamp(0.78rem, 1.4vw, 1rem);
  padding: clamp(1.15rem, 2.35vw, 1.85rem);
}

.sm-command-output::after {
  content: "";
  position: absolute;
  inset: 1rem 1rem auto auto;
  width: clamp(2.4rem, 5vw, 4.3rem);
  height: 0.72rem;
  background: var(--sm-lime);
}

.sm-command-output > span {
  display: inline-flex;
  width: max-content;
  max-width: calc(100% - 5.5rem);
  align-items: center;
  border: 2px solid #f9f1da10;
  padding: 0.35rem 0.52rem;
  color: var(--sm-muted);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-command-output h3 {
  max-width: 100%;
  color: var(--sm-lime);
  font-size: clamp(2rem, 4.4vw, 4.45rem);
  font-weight: 800;
  line-height: 0.88;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

.sm-command-output p {
  max-width: none;
  color: var(--sm-cream);
  font-size: clamp(0.98rem, 1.2vw, 1.1rem);
  font-weight: 700;
  line-height: 1.45;
}

.sm-command-output code {
  display: block;
  max-width: 100%;
  min-width: 0;
  overflow-x: auto;
  border: 2px solid #f9f1da10;
  background: #000;
  padding: 0.95rem;
  color: var(--sm-lime);
  font-size: clamp(0.82rem, 1vw, 0.98rem);
  line-height: 1.45;
  overflow-wrap: anywhere;
  white-space: normal;
  word-break: break-word;
}

.sm-command-output strong {
  align-self: end;
  border-top: 2px solid #f9f1da10;
  padding-top: 0.95rem;
  color: var(--sm-cream);
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.45;
}

.sm-setup {
  position: relative;
  overflow: hidden;
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-setup::after {
  content: "";
  position: absolute;
  inset: 0 0 0 auto;
  width: clamp(0.65rem, 1.4vw, 1.15rem);
  background: var(--sm-black);
}

.sm-setup .sm-pixel-label {
  border-color: var(--sm-black);
  background: var(--sm-black);
  color: var(--sm-lime);
}

.sm-setup .sm-section-head h2,
.sm-setup .sm-section-head p:not(.sm-pixel-label) {
  color: var(--sm-black);
}

.sm-setup-console {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: clamp(2rem, 5vw, 4rem);
  border: 0px;
  background: var(--sm-cream);
  box-shadow: 0 0 3.8rem #00000054;
}

.sm-setup-console article {
  display: grid;
  min-height: 18rem;
  align-content: start;
  gap: 0.8rem;
  border-left: 2px solid #00000041;
  padding: 1.2rem;
}

.sm-setup-console article:first-child {
  border-left: 0;
}

.sm-setup-console span {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 800;
}

.sm-setup-console h3 {
  color: var(--sm-black);
  font-size: clamp(1.45rem, 2.8vw, 2.6rem);
  font-weight: 800;
  line-height: 0.92;
  text-transform: uppercase;
}

.sm-setup-console p {
  color: #39362f;
  font-weight: 600;
  line-height: 1.45;
}

.sm-safety {
  position: relative;
  overflow: hidden;
  background: var(--sm-black);
}

.sm-safety::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: clamp(0.65rem, 1.4vw, 1.15rem);
  background: var(--sm-lime);
}

.sm-safety-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(20rem, 1.18fr);
  gap: clamp(2rem, 6vw, 6rem);
  align-items: start;
}

.sm-safety .sm-button {
  width: max-content;
  margin-top: 1rem;
}

.sm-rule-stack {
  border: 0px;
  box-shadow: 0 0 3.8rem #ccff001f;
  background: var(--sm-panel);
}

.sm-rule-stack div {
  display: grid;
  grid-template-columns: 12rem minmax(0, 1fr);
  gap: 1rem;
  border-top: 1px solid #f9f1da12;
  padding: clamp(1rem, 2vw, 1.45rem);
}

.sm-rule-stack div:first-child {
  border-top: 0;
}

.sm-rule-stack strong {
  color: var(--sm-lime);
  font-size: 1rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-rule-stack p {
  color: var(--sm-muted);
  font-weight: 600;
  line-height: 1.5;
}

.sm-final-cta {
  background: var(--sm-panel);
  padding-block: clamp(4rem, 8vw, 8rem);
}

.sm-final-cta .sm-page {
  display: grid;
  gap: 1.25rem;
}

.sm-final-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.sm-footer {
  background: var(--sm-black);
  color: var(--sm-muted);
  padding-block: 2.25rem;
}

.sm-footer-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 2rem;
  align-items: center;
}

.sm-footer strong,
.sm-footer a:hover {
  color: var(--sm-lime);
}

.sm-footer span {
  display: block;
  margin-top: 0.3rem;
}

.sm-footer nav {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 0.9rem;
  font-weight: 700;
}

/* Authenticated app */
.sm-app-shell {
  display: grid;
  min-height: 100vh;
  grid-template-columns: 17.5rem minmax(0, 1fr);
  background: var(--sm-black);
  color: var(--sm-cream);
}

.sm-app-sidebar {
  position: sticky;
  top: 0;
  display: grid;
  height: 100vh;
  grid-template-rows: auto minmax(0, 1fr) auto;
  border-right: 2px solid var(--sm-line);
  background: var(--sm-panel);
}

.sm-app-sidebar-brand {
  border-bottom: 2px solid var(--sm-line);
  padding: 1.15rem;
}

.sm-app-nav {
  display: grid;
  align-content: start;
  gap: 0;
}

.sm-app-nav a {
  display: grid;
  grid-template-columns: 3.2rem minmax(0, 1fr);
  align-items: center;
  border-bottom: 2px solid var(--sm-line);
  color: var(--sm-muted);
  font-weight: 900;
}

.sm-app-nav a span {
  display: grid;
  min-height: 3.4rem;
  place-items: center;
  border-right: 2px solid var(--sm-line);
  color: var(--sm-lime);
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.sm-app-nav a[data-active="true"],
.sm-app-nav a:hover {
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-app-nav a[data-active="true"] span,
.sm-app-nav a:hover span {
  border-right-color: var(--sm-black);
  color: var(--sm-black);
}

.sm-app-user {
  display: grid;
  grid-template-columns: 3rem minmax(0, 1fr);
  gap: 0.8rem;
  border-top: 2px solid var(--sm-line);
  padding: 1rem;
}

.sm-app-user img,
.sm-app-user > span {
  display: grid;
  width: 3rem;
  height: 3rem;
  place-items: center;
  border: 2px solid #f9f1da10;
  background: var(--sm-black);
  color: var(--sm-lime);
  font-weight: 800;
  object-fit: cover;
}

.sm-app-user strong,
.sm-app-user small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sm-app-user strong {
  color: var(--sm-cream);
  font-size: 0.92rem;
}

.sm-app-user small {
  color: var(--sm-muted);
  font-size: 0.78rem;
}

.sm-app-user button {
  grid-column: 1 / -1;
  border: 2px solid var(--sm-line);
  background: var(--sm-panel);
  padding: 0.72rem;
  color: var(--sm-muted);
  cursor: pointer;
  font-weight: 900;
}

.sm-app-user button:hover {
  border-color: var(--sm-lime);
  color: var(--sm-lime);
}

.sm-app-main {
  min-width: 0;
  background: var(--sm-black);
}

.sm-app-mobile-bar {
  display: none;
}

.sm-app-content {
  width: min(100% - clamp(1rem, 3vw, 3rem), 1380px);
  margin-inline: auto;
  padding-block: clamp(1.5rem, 3vw, 3rem);
}

.sm-app-content > div,
.sm-auth-page > div,
.sm-marketing-header + main {
  color: var(--sm-cream);
}

.sm-app-content header,
.sm-app-content .app-live-hero,
.sm-marketing-header + main > header,
.sm-marketing-header + main .app-live-hero {
  border: 2px solid #f9f1da10;
  background: var(--sm-panel);
  padding: clamp(1rem, 2.5vw, 2rem);
}

.sm-app-content header h1,
.app-live-hero h1,
.sm-auth-page h1 {
  color: var(--sm-cream);
  font-size: clamp(2.4rem, 5vw, 4.8rem);
  font-weight: 800;
  line-height: 0.9;
  text-transform: uppercase;
}

.sm-app-content header p,
.app-live-hero p:not(.app-live-kicker),
.sm-auth-page p {
  max-width: 48rem;
  color: var(--sm-muted);
  font-weight: 600;
  line-height: 1.5;
}

.sm-app-content .space-y-8 > * + *,
.sm-app-content .space-y-6 > * + * {
  margin-top: 1.25rem !important;
}

.sm-app-content .grid {
  gap: 1rem !important;
}

.sm-app-content .sm-card,
.sm-auth-page .sm-card,
.app-launch-feature,
.app-launch-tape,
.app-activity-console,
.app-live-stats,
.sm-command-ledger {
  border: 2px solid #f9f1da10 !important;
  background: var(--sm-panel) !important;
}

.sm-app-content .sm-card h2,
.sm-app-content .sm-card h3,
.sm-auth-page .sm-card h1 {
  color: var(--sm-cream);
}

.sm-app-content .divide-y > * + *,
.app-launch-row,
.app-activity-row,
.app-console-head,
.app-tape-head {
  border-top: 2px solid var(--sm-line) !important;
}

.sm-app-content :where(button, .inline-flex, .app-live-link),
.sm-auth-page :where(button, .inline-flex),
.app-live-link {
  border: 2px solid #f9f1da10 !important;
  background: var(--sm-panel) !important;
  color: var(--sm-cream) !important;
}

.sm-app-content :where(button, .inline-flex):hover,
.sm-auth-page :where(button, .inline-flex):hover,
.app-live-link:hover {
  border-color: var(--sm-lime) !important;
  color: var(--sm-lime) !important;
}

.sm-app-content :where(button.bg-primary, .bg-primary),
.sm-auth-page :where(button.bg-primary, .bg-primary),
.sm-app-content .text-primary.bg-transparent {
  border-color: var(--sm-lime) !important;
  background: var(--sm-lime) !important;
  color: var(--sm-black) !important;
}

.app-live-page {
  display: grid;
  gap: 1rem;
}

.app-live-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: start;
}

.app-live-kicker {
  display: inline-flex;
  width: max-content;
  border: 2px solid var(--sm-lime);
  background: var(--sm-lime);
  padding: 0.32rem 0.5rem;
  color: var(--sm-black) !important;
  font-size: 0.74rem;
  font-weight: 800;
  text-transform: uppercase;
}

.app-live-signal {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border: 2px solid var(--sm-lime);
  padding: 0.5rem 0.65rem;
  color: var(--sm-lime);
  font-size: 0.82rem;
  font-weight: 800;
  text-transform: uppercase;
}

.app-live-signal span {
  width: 0.65rem;
  height: 0.65rem;
  background: var(--sm-lime);
  animation: sm-router-tick 1.4s ease-in-out infinite;
}

.app-live-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.app-live-stats div {
  display: grid;
  gap: 0.3rem;
  border-left: 2px solid var(--sm-line);
  padding: 1rem;
}

.app-live-stats div:first-child {
  border-left: 0;
}

.app-live-stats span,
.app-console-head span,
.app-tape-head span {
  color: var(--sm-muted);
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
}

.app-live-stats strong {
  color: var(--sm-lime);
  font-size: clamp(1.5rem, 3vw, 2.4rem);
  font-weight: 800;
  line-height: 1;
}

.app-launch-feature {
  display: grid;
  grid-template-columns: 9rem minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: stretch;
  padding: 1rem;
}

.app-launch-art {
  display: grid;
  min-height: 9rem;
  place-items: center;
  border: 2px solid var(--sm-line);
  background: var(--sm-black);
}

.app-launch-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.app-launch-art span {
  color: var(--sm-lime);
  font-size: 2.5rem;
  font-weight: 800;
}

.app-launch-copy h2 {
  color: var(--sm-lime);
  font-size: clamp(2.6rem, 6vw, 5rem);
  font-weight: 800;
  line-height: 0.88;
}

.app-launch-copy p,
.app-launch-meta {
  color: var(--sm-muted);
  font-weight: 600;
  line-height: 1.45;
}

.app-launch-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.75rem;
}

.app-launch-row,
.app-activity-row summary,
.app-public-activity-summary {
  display: grid;
  grid-template-columns: 8rem minmax(0, 1.4fr) 8rem minmax(7rem, 0.7fr) minmax(8rem, 0.8fr);
  gap: 1rem;
  align-items: center;
  padding: 0.9rem 1rem;
  color: var(--sm-cream);
}

.app-launch-row:hover,
.app-activity-row:hover {
  background: var(--sm-panel-2);
}

.app-launch-row strong,
.app-activity-row strong {
  color: var(--sm-cream);
  font-weight: 800;
}

.app-launch-row small,
.app-activity-row small {
  display: block;
  margin-top: 0.22rem;
  color: var(--sm-muted);
  font-size: 0.78rem;
}

.app-activity-response-preview {
  color: rgb(204 255 0 / 72%);
}

.app-status,
.app-activity-kind {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  border: 2px solid #f9f1da10;
  padding: 0.25rem 0.45rem;
  color: var(--sm-lime);
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
}

.app-console-head,
.app-tape-head {
  display: grid;
  grid-template-columns: 8rem minmax(0, 1.4fr) 8rem minmax(7rem, 0.7fr) minmax(8rem, 0.8fr);
  gap: 1rem;
  padding: 0.75rem 1rem;
}

.app-empty-state {
  padding: 2rem;
  color: var(--sm-muted);
  font-weight: 700;
  text-align: center;
}

.app-activity-row {
  display: block;
}

.app-activity-row summary {
  cursor: pointer;
  list-style: none;
}

.app-activity-row summary::-webkit-details-marker {
  display: none;
}

.app-activity-row pre {
  overflow: auto;
  border-top: 2px solid var(--sm-line);
  margin: 0;
  background: #000;
  padding: 1rem;
  color: var(--sm-muted);
  font-size: 0.78rem;
}

.app-activity-detail-panel {
  display: grid;
  gap: 1rem;
  border-top: 2px solid var(--sm-line);
  background: rgb(0 0 0 / 24%);
  padding: 1rem;
}

.app-activity-dialogue {
  display: grid;
  gap: 0.8rem;
}

.app-activity-message {
  display: grid;
  width: min(100%, 48rem);
  gap: 0.55rem;
  border: 1px solid #f9f1da14;
  border-radius: 16px;
  background: rgb(249 241 218 / 6%);
  padding: 0.9rem 1rem;
}

.app-activity-message-bot {
  justify-self: end;
  border-color: rgb(204 255 0 / 20%);
  background: rgb(204 255 0 / 8%);
}

.app-activity-message span,
.app-activity-meta {
  color: var(--sm-muted);
  font-size: 0.72rem;
  font-weight: 850;
  text-transform: uppercase;
}

.app-activity-message p,
.app-activity-note {
  margin: 0;
  color: var(--sm-cream);
  font-size: 0.95rem;
  line-height: 1.55;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.app-activity-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem 0.9rem;
  align-items: center;
}

.app-activity-meta a {
  color: var(--sm-lime);
  text-decoration: none;
}

.app-activity-meta a:hover {
  text-decoration: underline;
}

.app-history-console {
  display: grid;
  gap: 1rem;
  overflow: hidden;
  border: 1px solid var(--sm-line);
  border-radius: 20px;
  background: var(--sm-panel);
  padding: 1rem;
}

.app-history-console-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid var(--sm-line);
  padding: 0.25rem 0.25rem 1rem;
}

.app-history-console-head > div {
  display: grid;
  gap: 0.25rem;
}

.app-history-console-head span,
.app-history-console-head p,
.app-history-message span,
.app-history-meta {
  color: var(--sm-muted);
  font-size: 0.72rem;
  font-weight: 850;
  text-transform: uppercase;
}

.app-history-console-head h2 {
  margin: 0;
  color: var(--sm-cream);
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  line-height: 1;
}

.app-history-console-head p {
  max-width: 22rem;
  margin: 0;
  line-height: 1.35;
  text-align: right;
}

.app-history-feed {
  display: grid;
  gap: 0.9rem;
}

.app-history-card {
  display: grid;
  min-width: 0;
  gap: 1rem;
  border: 1px solid var(--sm-line);
  border-radius: 18px;
  background: rgb(249 241 218 / 4%);
  padding: 1rem;
}

.app-history-dialogue {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
}

.app-history-message,
.app-history-summary {
  display: grid;
  min-width: 0;
  gap: 0.6rem;
  border: 1px solid #f9f1da14;
  border-radius: 16px;
  background: rgb(0 0 0 / 18%);
  padding: 0.9rem;
}

.app-history-message-bot {
  border-color: rgb(204 255 0 / 20%);
  background: rgb(204 255 0 / 7%);
}

.app-history-message p,
.app-history-summary p {
  margin: 0;
  color: var(--sm-cream);
  font-size: 0.95rem;
  line-height: 1.55;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.app-history-summary strong {
  color: var(--sm-cream);
  font-size: 1rem;
}

.app-history-footer {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  border-top: 1px solid #f9f1da12;
  padding-top: 0.85rem;
}

.app-history-meta {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  text-transform: none;
}

.app-history-actions {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  justify-content: flex-end;
}

.app-history-meta > span,
.app-history-meta code,
.app-history-actions a,
.app-history-error {
  display: inline-flex;
  min-height: 1.85rem;
  align-items: center;
  border-radius: 999px;
  background: rgb(249 241 218 / 7%);
  color: var(--sm-muted);
  padding: 0 0.65rem;
  text-decoration: none;
}

.app-history-actions a {
  color: var(--sm-lime);
}

.app-history-error {
  color: #fca5a5;
}

.app-history-actions .app-status {
  min-height: 1.85rem;
}

.app-history-actions a:hover {
  text-decoration: underline;
}

@media (max-width: 820px) {
  .app-history-console {
    padding: 0.75rem;
  }

  .app-history-console-head {
    display: grid;
    align-items: start;
  }

  .app-history-console-head p {
    max-width: none;
    text-align: left;
  }

  .app-history-card {
    border-radius: 16px;
    padding: 0.8rem;
  }

  .app-history-dialogue {
    grid-template-columns: minmax(0, 1fr);
  }

  .app-history-footer {
    display: grid;
    align-items: start;
  }

  .app-history-actions {
    justify-content: flex-start;
  }
}

.app-console-rail {
  display: none;
}

.sm-auth-page {
  position: relative;
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-auth-page::before {
  content: "";
  position: absolute;
  right: clamp(1rem, 5vw, 5rem);
  bottom: clamp(1rem, 5vw, 4rem);
  width: min(34vw, 24rem);
  aspect-ratio: 16 / 10;
  background: url("/linkr-pixel-bot.jpg") center / cover;
  transform: scaleX(-1);
}

.sm-auth-page .sm-card {
  position: relative;
  z-index: 1;
  border-color: var(--sm-black) !important;
  background: var(--sm-cream) !important;
  color: var(--sm-black) !important;
}

.sm-auth-page h1,
.sm-auth-page p,
.sm-auth-page .text-muted-foreground {
  color: var(--sm-black) !important;
}

.sm-auth-page .sm-auth-note,
.sm-auth-page .sm-auth-note p {
  color: var(--sm-cream) !important;
}

/* Public pages */
.sm-marketing-header + main {
  width: 100% !important;
  max-width: none !important;
  margin-inline: auto !important;
  padding-block: clamp(1.5rem, 3vw, 3rem) !important;
}

.sm-home-rebuild > .sm-marketing-header + main {
  margin-top: 0 !important;
  padding-block: 0 !important;
}

.sm-home-rebuild > .sm-marketing-header + main > .sm-hero:first-child {
  margin-top: 0 !important;
}

/* Coin page */
.sm-coin-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 76% 18%, rgb(204 255 0 / 8%), transparent 24rem),
    linear-gradient(180deg, #060706 0%, var(--sm-black) 34rem);
  color: var(--sm-cream);
  overflow-x: clip;
}

.sm-coin-page .sm-coin-shell {
  width: min(100% - clamp(1rem, 3vw, 2rem), 1500px) !important;
  max-width: none !important;
  margin-inline: auto !important;
  padding: clamp(1rem, 2vw, 1.4rem) 0 clamp(2.5rem, 5vw, 4rem) !important;
}

.sm-coin-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(21rem, 25rem);
  gap: 0.75rem;
  align-items: start;
}

.sm-coin-main,
.sm-coin-side {
  display: grid;
  gap: 0.75rem;
  min-width: 0;
}

.sm-coin-layout > *,
.sm-coin-identity,
.sm-coin-chart-card,
.sm-coin-about,
.sm-coin-chart-wrap {
  min-width: 0;
}

.sm-coin-identity,
.sm-coin-chart-card,
.sm-coin-about,
.sm-coin-metric,
.sm-coin-trade-card,
.sm-coin-side-card,
.sm-coin-empty {
  border: 1px solid rgb(247 244 229 / 14%);
  border-radius: var(--sm-radius) !important;
  background: rgb(12 13 12 / 86%);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 3%);
}

.sm-coin-identity {
  display: grid;
  grid-template-columns: 5.25rem minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: start;
  min-height: 11.75rem;
  padding: 1rem;
}

.sm-coin-token-art {
  display: grid;
  overflow: hidden;
  width: 5rem;
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid var(--sm-lime);
  border-radius: var(--sm-radius) !important;
  background: #171a13;
  color: var(--sm-lime);
  font-family: var(--font-display);
  font-size: 1.55rem;
  font-weight: 900;
}

.sm-coin-token-art img,
.sm-coin-similar-list img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sm-coin-title-block {
  min-width: 0;
}

.sm-coin-title-line {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  align-items: baseline;
}

.sm-coin-title-line h1 {
  font-size: clamp(1.45rem, 2vw, 2.05rem);
  line-height: 1;
}

.sm-coin-title-line span {
  color: rgb(247 244 229 / 58%);
  font-family: var(--font-display);
  font-size: clamp(0.88rem, 1.1vw, 1rem);
  font-weight: 900;
  text-transform: uppercase;
}

.sm-coin-subline,
.sm-coin-about-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-top: 0.45rem;
  color: rgb(247 244 229 / 66%);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.sm-coin-subline span,
.sm-coin-about-meta span {
  border: 1px solid rgb(247 244 229 / 14%);
  border-radius: var(--sm-radius-sm) !important;
  padding: 0.2rem 0.42rem;
}

.sm-coin-title-block p {
  max-width: 42rem;
  margin-top: 1.15rem;
  color: rgb(247 244 229 / 86%);
  font-size: 0.95rem;
  font-weight: 650;
  line-height: 1.45;
}

.sm-coin-identity-actions {
  display: flex;
  gap: 0.45rem;
  justify-content: end;
}

.sm-coin-identity-actions button,
.sm-coin-links a,
.sm-coin-chart-tabs button,
.sm-coin-trade-tabs a,
.sm-coin-trade-submit,
.sm-coin-empty a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgb(247 244 229 / 14%);
  border-radius: var(--sm-radius) !important;
  background: rgb(247 244 229 / 5%);
  color: var(--sm-cream);
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
}

.sm-coin-identity-actions button {
  min-width: 0;
  min-height: 2.55rem;
  gap: 0.5rem;
  overflow: hidden;
  padding: 0 0.8rem;
  text-overflow: ellipsis;
}

.sm-coin-identity-actions button:first-child,
.sm-coin-trade-tabs a:first-child,
.sm-coin-trade-submit {
  border-color: transparent;
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-coin-identity-actions button:hover,
.sm-coin-links a:hover,
.sm-coin-chart-tabs button:hover,
.sm-coin-trade-tabs a:hover,
.sm-coin-trade-submit:hover,
.sm-coin-empty a:hover {
  transform: translateY(-1px);
}

.sm-coin-links {
  display: flex;
  grid-column: 2 / -1;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-self: end;
}

.sm-coin-links a {
  min-height: 2rem;
  gap: 0.42rem;
  padding: 0 0.64rem;
  color: rgb(247 244 229 / 78%);
}

.sm-coin-chart-card {
  padding: 1rem;
}

.sm-coin-chart-summary {
  display: flex;
  gap: 1rem;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.sm-coin-chart-summary > div:first-child span,
.sm-coin-side-title small,
.sm-coin-progress-card p {
  color: rgb(247 244 229 / 62%);
}

.sm-coin-chart-summary > div:first-child span {
  display: block;
}

.sm-coin-chart-summary strong {
  display: inline-block;
  margin-top: 0.18rem;
  font-family: var(--font-display);
  font-size: clamp(2rem, 3vw, 3rem);
  font-weight: 900;
  line-height: 0.95;
}

.sm-coin-chart-summary small {
  margin-left: 0.45rem;
  font-size: 0.9rem;
  font-weight: 900;
}

.sm-coin-ath {
  min-width: min(100%, 24rem);
  text-align: right;
}

.sm-coin-ath span {
  display: block;
  height: 0.38rem;
  margin-bottom: 0.55rem;
  border-radius: 99rem !important;
  background:
    linear-gradient(
      90deg,
      rgb(247 244 229 / 22%),
      rgb(204 255 0 / 86%) 64%,
      rgb(247 244 229 / 24%)
    ),
    rgb(247 244 229 / 10%);
}

.sm-coin-ath small {
  margin: 0 0.38rem 0 0;
  color: rgb(247 244 229 / 58%);
}

.sm-coin-ath strong {
  font-size: 1rem;
}

.sm-coin-chart-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  align-items: center;
  margin-bottom: 0.55rem;
}

.sm-coin-chart-tabs button {
  flex: 0 0 auto;
  min-height: 2.15rem;
  gap: 0.45rem;
  padding: 0 0.76rem;
}

.sm-coin-chart-tabs button[data-active="true"] {
  color: var(--sm-lime);
}

.sm-coin-chart-tabs button:disabled {
  cursor: not-allowed;
  color: rgb(247 244 229 / 32%);
}

.sm-coin-chart-wrap {
  overflow: hidden;
  border-top: 1px solid rgb(247 244 229 / 8%);
  border-bottom: 1px solid rgb(247 244 229 / 8%);
  background:
    linear-gradient(rgb(247 244 229 / 4%) 1px, transparent 1px),
    linear-gradient(90deg, rgb(247 244 229 / 3%) 1px, transparent 1px), #101110;
  background-size:
    100% 25%,
    8.5% 100%,
    auto;
}

.sm-coin-chart-state {
  display: grid;
  min-height: 30rem;
  place-items: center;
  border-top: 1px solid rgb(247 244 229 / 8%);
  border-bottom: 1px solid rgb(247 244 229 / 8%);
  background:
    linear-gradient(rgb(247 244 229 / 4%) 1px, transparent 1px),
    linear-gradient(90deg, rgb(247 244 229 / 3%) 1px, transparent 1px), #101110;
  background-size:
    100% 25%,
    8.5% 100%,
    auto;
  color: rgb(247 244 229 / 62%);
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 900;
  text-align: center;
}

.sm-coin-chart-wrap svg {
  display: block;
  width: 100%;
  min-height: 30rem;
}

.sm-coin-chart-label,
.sm-coin-chart-ohcl,
.sm-coin-chart-axis,
.sm-coin-chart-volume,
.sm-coin-current-text {
  font-family: var(--font-mono);
  font-size: 12px;
}

.sm-coin-chart-label {
  fill: rgb(247 244 229 / 66%);
}

.sm-coin-chart-ohcl,
.sm-coin-chart-volume {
  fill: var(--sm-lime);
}

.sm-coin-chart-grid-line {
  stroke: rgb(247 244 229 / 8%);
  stroke-width: 1;
}

.sm-coin-chart-axis {
  fill: rgb(247 244 229 / 54%);
}

.sm-coin-candle-wick {
  stroke-width: 1.3;
}

.sm-coin-candle-body {
  rx: 1;
}

.is-up .sm-coin-candle-wick,
.is-up .sm-coin-candle-body {
  stroke: #ccff00;
  fill: #ccff00;
}

.is-down .sm-coin-candle-wick,
.is-down .sm-coin-candle-body {
  stroke: #ff5d66;
  fill: #ff5d66;
}

.sm-coin-volume-bar {
  opacity: 0.34;
}

.is-up .sm-coin-volume-bar {
  fill: #ccff00;
}

.is-down .sm-coin-volume-bar {
  fill: #ff5d66;
}

.sm-coin-current-line {
  stroke: url("#sm-coin-current-line");
  stroke-dasharray: 2 4;
  stroke-width: 1.4;
}

.sm-coin-current-pill {
  fill: var(--sm-lime);
}

.sm-coin-current-text {
  fill: var(--sm-black);
  font-weight: 900;
  text-anchor: middle;
}

.sm-coin-chart-watermark {
  fill: rgb(247 244 229 / 4%);
  font-family: var(--font-display);
  font-size: 7rem;
  font-weight: 900;
  letter-spacing: 0;
}

.sm-coin-chart-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 0.95rem;
  align-items: center;
  justify-content: end;
  padding-top: 0.8rem;
  color: var(--sm-cream);
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 900;
}

.sm-coin-chart-footer span:nth-last-child(3) {
  margin-left: auto;
}

.sm-coin-about {
  border-left-color: var(--sm-lime);
  border-left-width: 3px;
  padding: 1.25rem 1.45rem;
}

.sm-coin-about h2 {
  font-size: 1rem;
}

.sm-coin-about p {
  max-width: 65rem;
  margin-top: 0.9rem;
  color: rgb(247 244 229 / 88%);
  font-size: 0.94rem;
  font-weight: 650;
  line-height: 1.55;
}

.sm-coin-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.5rem;
}

.sm-coin-metric {
  min-height: 4.1rem;
  padding: 0.82rem 1rem;
  text-align: center;
}

.sm-coin-metric span {
  display: block;
