@media (max-width: 1240px) {
  .sm-coin-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-coin-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sm-coin-trade-card {
    grid-row: span 2;
  }
