  .sm-coin-chart-card,
  .sm-coin-trade-card,
  .sm-coin-side-card,
  .sm-coin-about {
    padding: 0.85rem;
  }

  .sm-coin-chart-summary strong {
    font-size: 2.1rem;
  }
