  .sm-setup-console article:nth-child(3) {
    border-left: 0;
    border-top: 3px solid var(--sm-black);
  }

  .sm-setup-console article:nth-child(4) {
    border-top: 3px solid var(--sm-black);
  }

  .sm-app-shell {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-app-sidebar {
    position: static;
    height: auto;
    border-right: 0;
  }

  .sm-app-nav {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .sm-app-user {
    display: none;
  }
