@media (max-width: 760px) {
  .sm-marketing-header-inner {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .sm-marketing-nav {
    display: none;
  }

  .sm-header-secondary {
    display: none;
  }

  .sm-hero h1 {
    font-size: clamp(3.4rem, 18vw, 5.8rem);
  }

  .sm-section-head h2,
  .sm-final-cta h2 {
    font-size: clamp(2.35rem, 11vw, 3.4rem);
  }

  .sm-hero-flow-list,
  .sm-command-picker,
  .sm-setup-console,
  .app-live-stats,
  .sm-app-nav {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-hero-flow-list li,
  .sm-command-picker button,
  .sm-setup-console article,
  .app-live-stats div {
    border-left: 0;
    border-top: 2px solid #f9f1da10;
  }

  .sm-hero-flow-list li:first-child,
  .sm-command-picker button:first-child,
  .sm-setup-console article:first-child,
  .app-live-stats div:first-child {
    border-top: 0;
  }

  .sm-command-board::before {
    min-height: 2.8rem;
  }

  .sm-command-picker {
    border-right: 0;
    border-bottom: 2px solid #f9f1da10;
  }

  .sm-command-picker button {
    min-height: 3.75rem;
    grid-template-columns: 2.1rem minmax(0, 1fr);
    align-items: center;
    border-left: 0;
    text-align: left;
  }

  .sm-command-output::after {
    width: 2.3rem;
  }

  .sm-command-output > span {
    max-width: calc(100% - 3.4rem);
  }

  .sm-action-lanes li,
  .sm-rule-stack div,
  .app-launch-feature,
  .app-launch-row,
  .app-activity-row summary,
  .app-public-activity-summary,
