.sm-hero-mascot {
  --sm-mascot-x: -0.45rem;
  --sm-mascot-y: -2.35rem;
  position: relative;
  display: grid;
  align-self: center;
  justify-self: center;
  width: clamp(22rem, 24vw, 24.8rem);
  animation: sm-mascot-float 5.8s ease-in-out infinite;
  transform: translate3d(var(--sm-mascot-x), var(--sm-mascot-y), 0);
  transform-origin: center;
  will-change: transform;
}

.sm-hero-mascot::before {
  content: "";
  position: absolute;
  inset: 7% -18% 2%;
  z-index: -1;
  background: radial-gradient(
    ellipse at 50% 48%,
    rgb(204 255 0 / 4%) 0%,
    rgb(204 255 0 / 2%) 30%,
    rgb(204 255 0 / 0.5%) 50%,
    transparent 74%
  );
  filter: blur(28px);
  transform-origin: center;
  animation: sm-mascot-glow 4.8s ease-in-out infinite;
}

.sm-hero-mascot::after {
  content: "";
  position: absolute;
  inset: 32% 0 3%;
  z-index: -1;
  background: radial-gradient(ellipse at 50% 58%, rgb(204 255 0 / 1.5%) 0%, transparent 68%);
  filter: blur(34px);
  transform-origin: center;
  animation: sm-mascot-ground-glow 4.8s ease-in-out infinite;
}

.sm-hero-mascot img {
  display: block;
  width: 100%;
  height: auto;
  animation: sm-mascot-light 4.8s ease-in-out infinite;
  filter: drop-shadow(0 0 1.9rem rgb(204 255 0 / 7%));
}

@keyframes sm-mascot-float {
  0%,
  100% {
    transform: translate3d(var(--sm-mascot-x), calc(var(--sm-mascot-y) + 0.18rem), 0)
      rotate(-0.35deg);
  }

  50% {
    transform: translate3d(var(--sm-mascot-x), calc(var(--sm-mascot-y) - 0.9rem), 0) rotate(0.35deg);
  }
}

@keyframes sm-mascot-glow {
  0%,
  100% {
    opacity: 0.12;
    transform: scale(0.96);
  }

  50% {
    opacity: 0.18;
    transform: scale(1.08);
  }
}

@keyframes sm-mascot-ground-glow {
  0%,
  100% {
    opacity: 0.06;
    transform: scaleX(0.94) scaleY(0.9);
  }

  50% {
    opacity: 0.1;
    transform: scaleX(1.08) scaleY(1);
  }
}

@keyframes sm-mascot-light {
  0%,
  100% {
    filter: drop-shadow(0 0 1.35rem rgb(204 255 0 / 8%));
  }

  50% {
    filter: drop-shadow(0 0 2.35rem rgb(204 255 0 / 14%));
  }
}

