/* Light dashboard redesign inspired by the provided 2026-06-30 reference image. */
:root {
  --sm-lime: #ccff00;
  --sm-lime-hover: #ccff00;
  --sm-green-soft: #eaf8ee;
  --sm-black: #0a0d0b;
  --sm-muted: #66706b;
  --sm-cream: #ffffff;
  --sm-panel: #ffffff;
  --sm-panel-2: #fbfcfb;
  --sm-hero-header-bg: #ffffff;
  --sm-line: #e2e7e3;
  --sm-line-strong: #cbd6cf;
  --sm-black-line: #0a0d0b;
  --sm-grid-line: transparent;
  --sm-radius: 8px;
  --sm-radius-sm: 6px;
}

html,
body {
  background: #ffffff;
  color: var(--sm-black);
}

body {
  color-scheme: light;
}

body :where(.rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl, .rounded-full) {
  border-radius: var(--sm-radius) !important;
}

body :where(button, a, input, textarea, select):focus-visible {
  outline: 2px solid var(--sm-lime);
  outline-offset: 3px;
}

body :where(input, textarea, select) {
  border: 1px solid var(--sm-line) !important;
  background: #ffffff !important;
  color: var(--sm-black) !important;
}

body .text-muted-foreground {
  color: var(--sm-muted) !important;
}

body .text-primary {
  color: var(--sm-lime) !important;
}

body .bg-primary {
  background: var(--sm-lime) !important;
}

body .bg-background,
body .bg-surface,
body .bg-muted,
body .bg-surface\/60,
body .bg-surface-elevated\/60,
body .bg-muted\/60 {
  background: #ffffff !important;
}

body .border-border,
body .border-input {
  border-color: var(--sm-line) !important;
}

body .sm-card {
  border: 1px solid var(--sm-line) !important;
  background: #ffffff !important;
  color: var(--sm-black) !important;
  border-radius: var(--sm-radius) !important;
}

body .sm-mono,
body code {
  color: var(--sm-black);
}

.sm-home-rebuild,
.sm-marketing-header + main,
.sm-auth-page,
.sm-app-shell,
.app-live-page,
.sm-coin-page {
  min-height: 100vh;
  background: #ffffff !important;
  color: var(--sm-black) !important;
}

.sm-marketing-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid var(--sm-line);
  background: rgb(255 255 255 / 96%);
  backdrop-filter: blur(12px);
}

.sm-marketing-header-inner {
  display: grid;
  width: min(100% - 48px, 1720px);
  min-height: 86px;
  margin-inline: auto;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 28px;
  align-items: center;
}

.sm-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--sm-black);
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2vw, 1.75rem);
  font-weight: 850;
  letter-spacing: 0;
  text-transform: none;
}

.sm-logo img {
  width: 42px;
  height: 42px;
  object-fit: contain;
}

.sm-marketing-header .sm-logo {
  align-self: center;
  justify-self: start;
  width: auto;
  min-height: 0;
  justify-content: flex-start;
  margin-top: 0;
  background: transparent;
  padding: 0;
}

.sm-marketing-header .sm-logo img {
  background: transparent;
  padding: 0;
}

.sm-marketing-header .sm-logo span {
  display: inline-block;
  color: var(--sm-black);
  font-family: var(--font-display);
  font-size: clamp(1.32rem, 1.7vw, 1.68rem);
  font-weight: 900;
  line-height: 1;
  text-transform: none;
}

.sm-marketing-nav {
  display: flex;
  justify-content: center;
  gap: clamp(1.2rem, 2.4vw, 2.9rem);
  color: var(--sm-black);
  font-size: 0.92rem;
  font-weight: 700;
  text-transform: none;
}

.sm-marketing-nav a {
  position: relative;
  display: inline-flex;
  min-height: 86px;
  align-items: center;
  color: inherit;
}

.sm-marketing-nav a::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 54px;
  height: 3px;
  background: transparent;
  transform: translateX(-50%);
}

.sm-marketing-nav a[data-active="true"]::after,
.sm-marketing-nav a:hover::after {
  background: var(--sm-lime);
}

.sm-marketing-nav a:hover {
  color: var(--sm-black);
}

.sm-header-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.sm-header-secondary,
.sm-header-primary,
.sm-button {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius) !important;
  padding-inline: 22px;
  color: var(--sm-black);
  font-size: 0.92rem;
  font-weight: 800;
  text-transform: none;
}

.sm-header-secondary,
.sm-button-secondary {
  background: #ffffff;
}

.sm-header-primary,
.sm-button-primary {
  border-color: var(--sm-lime);
  background: var(--sm-lime);
  color: var(--sm-black);
}

.sm-header-primary:hover,
.sm-button-primary:hover {
  background: var(--sm-lime-hover);
  transform: translateY(-1px);
}

.sm-header-secondary:hover,
.sm-button-secondary:hover {
  border-color: var(--sm-lime);
  color: var(--sm-black);
}

.sm-hero {
  min-height: auto;
  background: #ffffff;
  padding: clamp(24px, 3vw, 48px) 0 20px;
  overflow: clip;
}

.sm-hero::before {
  display: none;
}

.sm-hero-grid {
  display: grid;
  width: min(100% - 48px, 1720px);
  min-height: auto;
  margin-inline: auto;
  gap: clamp(28px, 2.8vw, 48px);
  align-items: start;
  padding: 0;
}

.sm-hero-auth .sm-hero-grid {
  grid-template-areas:
    "copy mascot rail"
    "metrics mascot rail"
    "feed feed feed";
  grid-template-columns: minmax(360px, 0.85fr) minmax(520px, 1.1fr) minmax(280px, 300px);
}

.sm-hero-public .sm-hero-grid {
  grid-template-areas:
    "copy mascot"
    "metrics mascot"
    "feed feed";
  grid-template-columns: minmax(540px, 0.92fr) minmax(560px, 1.08fr);
}

.sm-hero-copy {
  grid-area: copy;
  display: grid;
  max-width: 680px;
  align-content: center;
  padding: clamp(44px, 4.8vw, 76px) 0 0;
}

.sm-hero h1 {
  color: var(--sm-black);
  font-size: clamp(4rem, 4.55vw, 5.05rem);
  font-weight: 900;
  line-height: 0.98;
  text-transform: none;
}

.sm-hero h1 span {
  display: block;
}

.sm-hero h1 span:last-child {
  color: var(--sm-lime);
}

.sm-hero-copy > p {
  max-width: 520px;
  margin-top: 22px;
  color: #5f675f;
  font-size: clamp(1.02rem, 1.2vw, 1.18rem);
  font-weight: 500;
  line-height: 1.46;
}

.sm-hero-copy > p:not(.sm-pixel-label) {
  color: #5f675f;
}

.sm-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 30px;
}

.sm-home-metrics {
  grid-area: metrics;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  width: min(100%, 760px);
  margin-top: clamp(-12px, 1vw, 10px);
  border-top: 1px solid var(--sm-line);
  border-bottom: 1px solid var(--sm-line);
}

.sm-home-metrics div {
  display: grid;
  min-height: 86px;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 14px;
  align-items: center;
  border-left: 1px solid var(--sm-line);
  padding: 14px 18px;
}

.sm-home-metrics div:first-child {
  border-left: 0;
}

.sm-home-metrics svg {
  grid-row: span 2;
  color: var(--sm-lime);
}

.sm-home-metrics strong {
  min-width: 0;
  color: var(--sm-black);
  font-size: clamp(1.25rem, 1.8vw, 1.58rem);
  font-weight: 850;
  line-height: 1;
}

.sm-home-metrics span {
  color: var(--sm-muted);
  font-size: 0.84rem;
}

.sm-hero-visual {
  display: grid;
  grid-template-columns: minmax(290px, 0.72fr) minmax(430px, 1fr);
  gap: clamp(24px, 2.2vw, 36px);
  align-items: start;
  min-width: 0;
  padding-top: clamp(10px, 2vw, 28px);
}

.sm-hero-mascot {
  grid-area: mascot;
  position: relative;
  display: grid;
  width: min(100%, clamp(390px, 31vw, 560px));
  min-height: clamp(390px, 35vw, 540px);
  place-items: center;
  justify-self: center;
  align-self: start;
  perspective: 1200px;
  isolation: isolate;
  --sm-mascot-scroll: 0;
  --sm-mascot-x: 0px;
  --sm-mascot-y: 0px;
  --sm-mascot-z: 0px;
  --sm-mascot-rotate-x: -6deg;
  --sm-mascot-rotate-y: 8deg;
  --sm-mascot-ring: 0deg;
  --sm-mascot-ring-a: 0deg;
  --sm-mascot-ring-b: 0deg;
  --sm-mascot-ring-c: 0deg;
}

.sm-hero-mascot::before,
.sm-hero-mascot::after {
  display: none;
}

.sm-hero-depth-scene {
  position: relative;
  width: min(100%, clamp(360px, 28vw, 520px));
  aspect-ratio: 1;
  transform: translate3d(var(--sm-mascot-x), var(--sm-mascot-y), var(--sm-mascot-z))
    rotateX(var(--sm-mascot-rotate-x)) rotateY(var(--sm-mascot-rotate-y));
  transform-style: preserve-3d;
  transition: transform 120ms ease-out;
  will-change: transform;
}

.sm-hero-depth-grid {
  position: absolute;
  right: 10%;
  bottom: 9%;
  left: 10%;
  height: 34%;
  border: 1px solid rgb(80 186 96 / 28%);
  background:
    linear-gradient(rgb(80 186 96 / 18%) 1px, transparent 1px),
    linear-gradient(90deg, rgb(80 186 96 / 18%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(245 251 246 / 88%), rgb(225 246 229 / 54%));
  background-size:
    24px 24px,
    24px 24px,
    100% 100%;
  box-shadow: 0 26px 60px rgb(47 141 64 / 12%);
  transform: translateZ(-120px) rotateX(72deg);
  transform-origin: center bottom;
  animation: sm-hero-grid-drift 8s ease-in-out infinite;
}

.sm-hero-orbit,
.sm-hero-satellite {
  position: absolute;
  pointer-events: none;
}

.sm-hero-orbit {
  inset: 11%;
  border: 1px solid rgb(80 186 96 / 22%);
  border-radius: 999px;
  transform-style: preserve-3d;
  transform-origin: center;
  will-change: transform;
}

.sm-hero-orbit-a {
  transform: translateZ(-40px) rotateX(68deg) rotateZ(var(--sm-mascot-ring-a));
  animation: sm-hero-orbit-a-spin 22s linear infinite;
}

.sm-hero-orbit-b {
  inset: 18% 7%;
  border-color: rgb(16 20 17 / 12%);
  transform: translateZ(10px) rotateY(64deg) rotateZ(var(--sm-mascot-ring-b));
  animation: sm-hero-orbit-b-spin 28s linear infinite reverse;
}

.sm-hero-orbit-c {
  inset: 22% 15%;
  border-color: rgb(80 186 96 / 18%);
  transform: translateZ(60px) rotateX(18deg) rotateY(42deg) rotateZ(var(--sm-mascot-ring-c));
  animation: sm-hero-orbit-c-spin 34s linear infinite;
}

.sm-hero-satellite {
  display: block;
  width: clamp(34px, 3.3vw, 54px);
  height: clamp(26px, 2.4vw, 42px);
  border: 1px solid rgb(16 20 17 / 12%);
  border-radius: 8px;
  background:
    linear-gradient(
      90deg,
      rgb(80 186 96 / 0%) 0 42%,
      rgb(80 186 96 / 40%) 42% 58%,
      transparent 58%
    ),
    rgb(255 255 255 / 86%);
  box-shadow: 0 18px 34px rgb(10 13 11 / 9%);
  transform-style: preserve-3d;
  will-change: transform;
}

.sm-hero-satellite-a {
  top: 21%;
  left: 2%;
  transform: translateZ(115px) rotateY(36deg) rotateX(9deg);
  animation: sm-hero-satellite-a-float 7.5s ease-in-out infinite;
}

.sm-hero-satellite-b {
  top: 31%;
  right: 4%;
  transform: translateZ(96px) rotateY(-31deg) rotateX(-4deg);
  animation: sm-hero-satellite-b-float 8.7s ease-in-out infinite;
}

.sm-hero-satellite-c {
  right: 21%;
  bottom: 18%;
  transform: translateZ(150px) rotateY(-16deg) rotateX(18deg);
  animation: sm-hero-satellite-c-float 9.4s ease-in-out infinite;
}

.sm-hero-mascot-core {
  position: absolute;
  inset: 5%;
  display: grid;
  place-items: center;
  transform: translateZ(92px);
  transform-style: preserve-3d;
  will-change: transform;
}

.sm-hero-mascot-core img {
  display: block;
  width: 100%;
  height: auto;
  transform: translateZ(42px);
  filter: drop-shadow(0 24px 34px rgb(10 13 11 / 10%));
  animation: sm-hero-mascot-breathe 6.8s ease-in-out infinite;
}

@keyframes sm-hero-grid-drift {
  0%,
  100% {
    background-position:
      0 0,
      0 0,
      0 0;
    opacity: 0.78;
  }

  50% {
    background-position:
      18px 10px,
      10px 18px,
      0 0;
    opacity: 1;
  }
}

@keyframes sm-hero-orbit-a-spin {
  from {
    transform: translateZ(-40px) rotateX(68deg) rotateZ(var(--sm-mascot-ring-a));
  }

  to {
    transform: translateZ(-40px) rotateX(68deg) rotateZ(calc(var(--sm-mascot-ring-a) + 360deg));
  }
}

@keyframes sm-hero-orbit-b-spin {
  from {
    transform: translateZ(10px) rotateY(64deg) rotateZ(var(--sm-mascot-ring-b));
  }

  to {
    transform: translateZ(10px) rotateY(64deg) rotateZ(calc(var(--sm-mascot-ring-b) + 360deg));
  }
}

@keyframes sm-hero-orbit-c-spin {
  from {
    transform: translateZ(60px) rotateX(18deg) rotateY(42deg) rotateZ(var(--sm-mascot-ring-c));
  }

  to {
    transform: translateZ(60px) rotateX(18deg) rotateY(42deg)
      rotateZ(calc(var(--sm-mascot-ring-c) + 360deg));
  }
}

@keyframes sm-hero-satellite-a-float {
  0%,
  100% {
    transform: translateZ(115px) translate3d(0, 0, 0) rotateY(36deg) rotateX(9deg);
  }

  50% {
    transform: translateZ(142px) translate3d(10px, -14px, 0) rotateY(48deg) rotateX(12deg);
  }
}

@keyframes sm-hero-satellite-b-float {
  0%,
  100% {
    transform: translateZ(96px) translate3d(0, 0, 0) rotateY(-31deg) rotateX(-4deg);
  }

  50% {
    transform: translateZ(128px) translate3d(-12px, 10px, 0) rotateY(-42deg) rotateX(-9deg);
  }
}

@keyframes sm-hero-satellite-c-float {
  0%,
  100% {
    transform: translateZ(150px) translate3d(0, 0, 0) rotateY(-16deg) rotateX(18deg);
  }

  50% {
    transform: translateZ(184px) translate3d(8px, -10px, 0) rotateY(-24deg) rotateX(24deg);
  }
}

@keyframes sm-hero-mascot-breathe {
  0%,
  100% {
    transform: translateZ(42px) translateY(0) scale(1);
    filter: drop-shadow(0 24px 34px rgb(10 13 11 / 10%));
  }

  50% {
    transform: translateZ(58px) translateY(-8px) scale(1.015);
    filter: drop-shadow(0 32px 42px rgb(10 13 11 / 13%));
  }
}

.sm-hero-feed {
  align-self: start;
  min-width: 0;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: #ffffff;
  box-shadow: 0 18px 52px rgb(10 13 11 / 5%);
  overflow: hidden;
}

.sm-hero-feed-band {
  position: relative;
  grid-area: feed;
  min-width: 0;
}

.sm-hero-feed-band::before {
  content: "";
  position: absolute;
  top: -18px;
  right: 0;
  left: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(80 186 96 / 42%), transparent);
}

.sm-hero-feed-band .sm-hero-feed {
  width: 100%;
  background:
    linear-gradient(
      90deg,
      rgb(231 248 234 / 54%),
      transparent 24%,
      transparent 76%,
      rgb(231 248 234 / 42%)
    ),
    #ffffff;
}

.sm-hero-feed-band .sm-feed-list {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  min-height: 142px;
}

.sm-hero-feed-band .sm-feed-state {
  grid-column: 1 / -1;
  min-height: 142px;
}

.sm-hero-feed-band .sm-feed-item {
  min-height: 142px;
  border-right: 1px solid var(--sm-line);
  border-bottom: 0;
}

.sm-hero-feed-band .sm-feed-item:last-child {
  border-right: 0;
}

.sm-hero-feed-band .sm-feed-item::after {
  display: none;
}

.sm-hero-feed-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  min-height: 56px;
  border-bottom: 1px solid var(--sm-line);
  padding-inline: 18px;
}

.sm-hero-feed-tabs {
  display: flex;
  gap: 34px;
  align-items: stretch;
  height: 56px;
}

.sm-hero-feed-tabs span {
  position: relative;
  display: inline-flex;
  align-items: center;
  color: var(--sm-muted);
  font-size: 0.9rem;
  font-weight: 750;
}

.sm-hero-feed-tabs span[data-active="true"] {
  color: var(--sm-black);
}

.sm-hero-feed-tabs span[data-active="true"]::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--sm-lime);
}

.sm-hero-feed select {
  height: 34px;
  border-radius: 6px !important;
  color: var(--sm-black);
  font-size: 0.82rem;
}

.sm-feed-list {
  display: grid;
}

.sm-feed-state {
  display: grid;
  min-height: 250px;
  place-items: center;
  padding: 28px;
  color: var(--sm-muted);
  text-align: center;
}

.sm-feed-item {
  position: relative;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 14px;
  border-bottom: 1px solid var(--sm-line);
  padding: 18px;
}

.sm-feed-item:last-child {
  border-bottom: 0;
}

.sm-feed-item::after {
  content: "";
  position: absolute;
  top: 64px;
  bottom: -1px;
  left: 40px;
  width: 1px;
  background: var(--sm-line);
}

.sm-feed-avatar {
  position: relative;
  z-index: 1;
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid var(--sm-line);
  border-radius: 8px;
  background: var(--sm-green-soft);
  color: var(--sm-black);
  font-size: 0.78rem;
  font-weight: 850;
  overflow: hidden;
}

.sm-feed-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sm-feed-main {
  min-width: 0;
}

.sm-feed-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  color: var(--sm-muted);
  font-size: 0.82rem;
}

.sm-feed-meta strong {
  color: var(--sm-black);
}

.sm-feed-main h3 {
  margin-top: 5px;
  color: var(--sm-black);
  font-size: 0.96rem;
  font-weight: 850;
  line-height: 1.25;
}

.sm-feed-main p {
  margin-top: 4px;
  color: var(--sm-black);
  font-size: 0.92rem;
  line-height: 1.38;
}

.sm-feed-main code {
  display: block;
  margin-top: 9px;
  border: 1px solid #d8ebdd;
  border-radius: 6px;
  background: var(--sm-green-soft);
  padding: 8px 10px;
  color: #2f8d40;
  white-space: normal;
}

.sm-feed-actions {
  display: flex;
  max-width: 310px;
  margin-top: 12px;
  justify-content: space-between;
  color: var(--sm-muted);
}

.sm-feed-actions span {
  display: inline-flex;
}

.sm-feed-side {
  display: grid;
  justify-items: end;
  align-content: start;
  gap: 8px;
  min-width: 84px;
}

.sm-feed-side span {
  border-radius: 6px;
  background: var(--sm-green-soft);
  padding: 5px 8px;
  color: #2f8d40;
  font-size: 0.7rem;
  font-weight: 850;
  text-transform: uppercase;
}

.sm-feed-item[data-tone="warning"] .sm-feed-side span {
  background: #fff8e7;
  color: #9a670d;
}

.sm-feed-item[data-tone="danger"] .sm-feed-side span {
  background: #fff0f0;
  color: #b83232;
}

.sm-feed-side code {
  color: var(--sm-muted);
  font-size: 0.72rem;
}

.sm-feed-full-link {
  display: flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  border-top: 1px solid var(--sm-line);
  color: var(--sm-black);
  font-size: 0.86rem;
  font-weight: 800;
}

.sm-hero-rail {
  grid-area: rail;
  display: grid;
  gap: 14px;
  align-self: start;
}

.sm-rail-card {
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: #ffffff;
  padding: 18px;
}

.sm-rail-title,
.sm-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.sm-rail-title h2,
.sm-rail-card h2,
.sm-card-head h2 {
  color: var(--sm-black);
  font-size: 1rem;
  font-weight: 850;
}

.sm-portfolio-card > span {
  display: block;
  margin-top: 20px;
  color: var(--sm-muted);
  font-size: 0.86rem;
}

.sm-portfolio-total {
  margin-top: 6px;
}

.sm-portfolio-total strong {
  display: block;
  color: var(--sm-black);
  font-size: 1.8rem;
  line-height: 1.05;
}

.sm-portfolio-total div {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 7px;
}

.sm-portfolio-total small {
  color: var(--sm-muted);
}

.sm-portfolio-total b {
  color: #2f9a43;
  font-size: 0.86rem;
}

.sm-portfolio-total em {
  color: var(--sm-muted);
  font-size: 0.78rem;
  font-style: normal;
}

.sm-wallet-short button {
  margin-top: 10px;
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--sm-muted);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.8rem;
}

.sm-portfolio-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  margin-top: 22px;
}

.sm-portfolio-actions a {
  display: grid;
  min-width: 0;
  gap: 7px;
  justify-items: center;
  color: var(--sm-black);
  font-size: 0.75rem;
  font-weight: 800;
}

.sm-quick-list {
  display: grid;
  gap: 14px;
  margin-top: 18px;
}

.sm-quick-list :where(a, button) {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--sm-black);
  text-align: left;
}

.sm-quick-list button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.sm-quick-list strong,
.sm-quick-list small {
  display: block;
}

.sm-quick-list strong {
  font-size: 0.86rem;
}

.sm-quick-list small {
  margin-top: 2px;
  color: var(--sm-muted);
  font-size: 0.75rem;
}

.sm-rules-card {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  gap: 13px;
  align-items: center;
}

.sm-rules-card > svg {
  color: var(--sm-lime);
}

.sm-rules-card p {
  margin-top: 3px;
  color: var(--sm-muted);
  font-size: 0.78rem;
  line-height: 1.28;
}

.sm-rail-empty {
  display: grid;
  gap: 12px;
  margin-top: 16px;
  color: var(--sm-muted);
  font-size: 0.88rem;
}

.sm-rail-empty a {
  display: inline-flex;
  width: max-content;
  align-items: center;
  gap: 8px;
  color: var(--sm-black);
  font-weight: 850;
}

.sm-home-dashboard {
  padding: 12px 0 22px;
}

.sm-dashboard-grid {
  display: grid;
  width: min(100% - 48px, 1720px);
  margin-inline: auto;
  grid-template-columns: minmax(260px, 1fr) minmax(260px, 1fr) minmax(260px, 1fr) minmax(260px, 1fr);
  gap: 14px;
}

.sm-dashboard-card {
  min-width: 0;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: #ffffff;
  padding: 18px;
}

.sm-card-head a,
.sm-card-head span {
  border: 1px solid var(--sm-line);
  border-radius: 6px;
  padding: 7px 11px;
  color: var(--sm-black);
  font-size: 0.78rem;
  font-weight: 750;
}

.sm-table-list,
.sm-token-list,
.sm-achievement-list {
  display: grid;
  gap: 12px;
  margin-top: 18px;
}

.sm-rank-row,
.sm-token-row,
.sm-achievement-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  min-height: 42px;
  color: var(--sm-black);
  font-size: 0.84rem;
}

.sm-rank-row > span {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 999px;
  background: #fff5d8;
  color: #8f6814;
  font-size: 0.7rem;
  font-weight: 850;
}

.sm-rank-row small,
.sm-token-row small,
.sm-achievement-row small {
  color: var(--sm-muted);
}

.sm-rank-row b,
.sm-token-row b {
  color: #2f9a43;
  font-size: 0.78rem;
}

.sm-token-row {
  grid-template-columns: 34px minmax(0, 1fr) auto;
}

.sm-token-avatar {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 8px;
  background: var(--sm-green-soft);
  color: var(--sm-black);
  font-size: 0.7rem;
  font-weight: 850;
  overflow: hidden;
}

.sm-token-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sm-token-row strong,
.sm-token-row small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sm-achievement-row {
  grid-template-columns: 38px minmax(0, 1fr) auto;
}

.sm-achievement-row > span {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 8px;
  background: var(--sm-green-soft);
  color: #2f8d40;
}

.sm-achievement-row time {
  color: var(--sm-muted);
  font-size: 0.76rem;
}

.sm-empty-line {
  display: grid;
  min-height: 120px;
  place-items: center;
  border: 1px dashed var(--sm-line-strong);
  border-radius: var(--sm-radius);
  color: var(--sm-muted);
  font-size: 0.86rem;
  text-align: center;
}

.sm-command-tape {
  display: grid;
  grid-template-columns: minmax(168px, auto) minmax(0, 1fr);
  overflow: hidden;
  border-top: 1px solid var(--sm-line);
  border-bottom: 1px solid var(--sm-line);
  background: #ffffff;
  color: var(--sm-black);
}

.sm-command-label {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  border-right: 1px solid var(--sm-line);
  background: var(--sm-green-soft);
  padding-inline: 18px;
  color: var(--sm-black);
  font-size: 0.82rem;
  font-weight: 850;
}

.sm-command-label svg {
  color: var(--sm-lime);
}

.sm-tape-track {
  display: flex;
  min-width: 0;
  width: max-content;
  overflow: hidden;
  animation: sm-tape-roll 32s linear infinite;
}

.sm-tape-track span {
  position: relative;
  display: inline-flex;
  min-width: clamp(18rem, 19vw, 24rem);
  min-height: 50px;
  align-items: center;
  border-left: 1px solid var(--sm-line);
  padding-inline: 34px 58px;
  color: var(--sm-black);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.sm-tape-track span::before {
  content: ">";
  margin-right: 3px;
  color: var(--sm-muted);
}

.sm-tape-track span::after {
  content: "->";
  position: absolute;
  right: 24px;
  color: var(--sm-lime);
  font-size: 1.4rem;
}

.sm-home-section,
.sm-final-cta {
  width: min(100% - 48px, 1380px);
  margin-inline: auto;
  padding-block: clamp(56px, 7vw, 96px);
}

.sm-home-section-copy {
  max-width: 760px;
}

.sm-home-section-copy > p {
  color: var(--sm-lime);
  font-size: 0.86rem;
  font-weight: 850;
}

.sm-home-section-copy h2,
.sm-final-cta h2 {
  margin-top: 8px;
  color: var(--sm-black);
  font-size: clamp(2.4rem, 4.4vw, 4.5rem);
  font-weight: 900;
  line-height: 1;
  text-transform: none;
}

.sm-command-grid,
.sm-setup-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  margin-top: 28px;
}

.sm-command-grid a,
.sm-setup-grid article {
  display: grid;
  min-width: 0;
  min-height: 142px;
  gap: 10px;
  align-content: start;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: #ffffff;
  padding: 18px;
}

.sm-command-grid strong,
.sm-setup-grid h3 {
  color: var(--sm-black);
  font-size: 1rem;
}

.sm-command-grid code {
  color: var(--sm-muted);
  overflow-wrap: anywhere;
}

.sm-setup-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.sm-setup-grid article > span {
  color: var(--sm-muted);
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.sm-setup-grid svg {
  color: var(--sm-lime);
}

.sm-setup-grid p {
  color: var(--sm-muted);
  font-size: 0.9rem;
  line-height: 1.4;
}

.sm-final-cta {
  display: grid;
  place-items: center;
  text-align: center;
}

.sm-final-cta > div {
  display: grid;
  max-width: 850px;
  justify-items: center;
}

.sm-final-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
  margin-top: 26px;
}

.sm-app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  background: #ffffff;
}

.sm-app-sidebar {
  border-right: 1px solid var(--sm-line);
  background: #ffffff;
}

.sm-app-nav a {
  border: 1px solid transparent;
  color: var(--sm-muted);
}

.sm-app-nav a[data-active="true"],
.sm-app-nav a:hover {
  border-color: var(--sm-line);
  background: var(--sm-green-soft);
  color: var(--sm-black);
}

.sm-app-main,
.sm-app-content {
  background: #ffffff;
  color: var(--sm-black);
}

.sm-app-content header,
.sm-app-content .app-live-hero,
.sm-marketing-header + main > header,
.sm-marketing-header + main .app-live-hero,
.app-live-stats,
.app-launch-feature,
.app-launch-tape,
.app-activity-console,
.sm-command-ledger,
.sm-auth-page .sm-card,
.sm-coin-identity,
.sm-coin-chart-card,
.sm-coin-about,
.sm-coin-metric,
.sm-coin-side-card,
.sm-coin-trade-card {
  border: 1px solid var(--sm-line) !important;
  border-radius: var(--sm-radius) !important;
  background: #ffffff !important;
  color: var(--sm-black) !important;
}

.app-live-hero h1,
.app-live-hero p,
.app-live-stats strong,
.app-launch-copy h2,
.app-activity-row,
.sm-coin-page,
.sm-coin-shell,
.sm-coin-title-line h1,
.sm-coin-chart-card,
.sm-coin-about h2 {
  color: var(--sm-black) !important;
}

.app-live-kicker,
.app-live-signal,
.app-status,
.app-activity-kind {
  border-radius: 6px !important;
}

.app-live-kicker,
.app-live-signal span,
.app-status-confirmed,
.app-status-completed,
.app-status-success,
.app-status-posted {
  background: var(--sm-green-soft) !important;
  color: #2f8d40 !important;
}

.app-live-stats span,
.app-launch-meta,
.app-tape-head,
.app-console-head,
.app-activity-row small,
.app-public-activity-summary,
.sm-coin-subline,
.sm-coin-about-meta,
.sm-coin-side-title small,
.sm-coin-info-list small {
  color: var(--sm-muted) !important;
}

.sm-auth-page {
  background: #ffffff !important;
}

.sm-auth-page .sm-card {
  box-shadow: 0 24px 60px rgb(10 13 11 / 8%);
}

@media (max-width: 1480px) {
  .sm-hero-auth .sm-hero-grid {
    grid-template-columns: minmax(350px, 0.85fr) minmax(570px, 1.2fr) minmax(270px, 290px);
  }

  .sm-hero h1 {
    font-size: clamp(3.7rem, 5vw, 4.9rem);
  }
}

@media (max-width: 1240px) {
  .sm-marketing-nav {
    gap: 1.2rem;
  }

  .sm-hero-auth .sm-hero-grid,
  .sm-hero-public .sm-hero-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-hero-auth .sm-hero-grid {
    grid-template-areas:
      "copy"
      "mascot"
      "metrics"
      "rail"
      "feed";
  }

  .sm-hero-public .sm-hero-grid {
    grid-template-areas:
      "copy"
      "mascot"
      "metrics"
      "feed";
  }

  .sm-hero-copy {
    max-width: 760px;
    padding-top: 0;
  }

  .sm-hero-visual {
    grid-template-columns: minmax(250px, 320px) minmax(0, 1fr);
    padding-top: 0;
  }

  .sm-hero-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .sm-dashboard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sm-command-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .sm-marketing-header-inner {
    min-height: 72px;
    grid-template-columns: auto auto;
    justify-content: space-between;
  }

  .sm-marketing-nav {
    display: none;
  }

  .sm-hero {
    min-height: auto;
    padding-block: 28px;
  }

  .sm-hero-visual {
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }

  .sm-hero-mascot {
    width: min(80vw, 390px);
    min-height: auto;
  }

  .sm-hero-depth-scene {
    width: min(100%, 360px);
  }

  .sm-hero-rail {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-home-metrics,
  .sm-dashboard-grid,
  .sm-command-grid,
  .sm-setup-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-home-metrics div,
  .sm-home-metrics div:first-child {
    border-top: 1px solid var(--sm-line);
    border-left: 0;
  }

  .sm-home-metrics div:first-child {
    border-top: 0;
  }

  .sm-app-shell {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 640px) {
  .sm-hero .sm-hero-grid {
    display: flex !important;
    width: calc(100vw - 28px) !important;
    max-width: calc(100vw - 28px) !important;
    margin-right: 14px !important;
    margin-left: 14px !important;
    padding-top: clamp(330px, 86vw, 390px) !important;
    flex-direction: column !important;
    align-items: stretch !important;
    overflow: visible !important;
  }

  .sm-marketing-header-inner,
  .sm-hero-grid,
  .sm-dashboard-grid,
  .sm-home-section,
  .sm-final-cta {
    width: min(100% - 28px, 420px);
  }

  .sm-logo img {
    width: 34px;
    height: 34px;
  }

  .sm-logo span {
    font-size: 1.25rem;
  }

  .sm-header-secondary {
    display: none;
  }

  .sm-header-primary {
    min-height: 40px;
    padding-inline: 14px;
    font-size: 0.82rem;
  }

  .sm-hero h1 {
    font-size: clamp(2.7rem, 14vw, 4rem);
  }

  .sm-hero-copy > p {
    font-size: 0.95rem;
  }

  .sm-hero-actions,
  .sm-final-actions {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-button {
    width: 100%;
  }

  .sm-hero-feed-head {
    grid-template-columns: minmax(0, 1fr);
    gap: 10px;
    padding-block: 12px;
  }

  .sm-hero-feed-tabs {
    height: auto;
  }

  .sm-hero-feed-band .sm-feed-list {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-feed-item {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .sm-hero-feed-band .sm-feed-item {
    border-right: 0;
    border-bottom: 1px solid var(--sm-line);
  }

  .sm-hero-feed-band .sm-feed-item:last-child {
    border-bottom: 0;
  }

  .sm-feed-side {
    grid-column: 2;
    justify-items: start;
    min-width: 0;
  }

  .sm-command-tape {
    grid-template-columns: minmax(0, 1fr);
  }

  .sm-command-label {
    min-height: 42px;
    border-right: 0;
    border-bottom: 1px solid var(--sm-line);
  }

  .sm-tape-track span {
    min-width: 16rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sm-hero-depth-scene,
  .sm-hero-depth-grid,
  .sm-hero-mascot-core img,
  .sm-hero-orbit,
  .sm-hero-satellite {
    transition: none !important;
    animation: none !important;
  }

  .sm-hero-depth-scene {
    transform: none !important;
  }
}

.sm-legal-page {
  min-height: 100vh;
  background: #ffffff;
  color: var(--sm-black);
}

.sm-legal-wrap {
  width: min(100% - 48px, 880px);
  margin: 0 auto;
  padding: 72px 0 96px;
}

.sm-legal-kicker {
  margin: 0 0 12px;
  color: var(--sm-lime);
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
}

.sm-legal-wrap h1 {
  margin: 0;
  color: var(--sm-black);
  font-family: var(--font-display);
  font-size: clamp(3rem, 7vw, 5rem);
  font-weight: 900;
  letter-spacing: 0;
  line-height: 0.98;
}

.sm-legal-updated {
  margin: 18px 0 44px;
  color: var(--sm-muted);
  font-size: 0.95rem;
}

.sm-legal-wrap section {
  border-top: 1px solid var(--sm-line);
  padding: 28px 0;
}

.sm-legal-wrap h2 {
  margin: 0 0 10px;
  color: var(--sm-black);
  font-size: 1.08rem;
  font-weight: 850;
  letter-spacing: 0;
}

.sm-legal-wrap p {
  max-width: 68ch;
  margin: 0;
  color: #4f584f;
  font-size: 1rem;
