@media (max-width: 640px) {
  .sm-legal-wrap {
    width: min(100% - 28px, 420px);
    padding: 48px 0 72px;
  }
}

/* Exchange-grade product redesign layer. */
:root {
  --sm-blue: #0052ff;
  --sm-blue-hover: #0646d8;
  --sm-blue-soft: #eef4ff;
  --sm-blue-wash: #f6f9ff;
  --sm-ink: #0a0b0d;
  --sm-ink-2: #20242c;
  --sm-muted: #5b6472;
  --sm-muted-2: #8a94a6;
  --sm-page: #f5f7fb;
  --sm-panel: #ffffff;
  --sm-panel-2: #f9fbff;
  --sm-line: #dfe5ef;
  --sm-line-strong: #c7d0de;
  --sm-lime: #ccff00;
  --sm-lime-hover: #ccff00;
  --sm-green-soft: #ecfdf3;
  --sm-warning-soft: #fff7df;
  --sm-danger-soft: #fff0f0;
  --sm-radius: 8px;
  --sm-radius-sm: 6px;
  --background: var(--sm-page);
  --foreground: var(--sm-ink);
  --surface: var(--sm-panel);
  --surface-elevated: var(--sm-panel);
  --card: var(--sm-panel);
  --card-foreground: var(--sm-ink);
  --primary: var(--sm-blue);
  --primary-foreground: #ffffff;
  --secondary: var(--sm-blue-soft);
  --secondary-foreground: var(--sm-blue);
  --muted: #eef2f7;
  --muted-foreground: var(--sm-muted);
  --accent: var(--sm-blue-soft);
  --accent-foreground: var(--sm-blue);
  --success: var(--sm-lime);
  --success-foreground: #ffffff;
  --warning: #b7791f;
  --warning-foreground: #15100a;
  --border: var(--sm-line);
  --input: var(--sm-line);
  --ring: var(--sm-blue);
  --chart-1: var(--sm-blue);
  --chart-2: var(--sm-lime);
  --chart-3: #7c3aed;
  --chart-4: #f59e0b;
  --chart-5: #64748b;
}

html,
body {
  background: var(--sm-page) !important;
  color: var(--sm-ink) !important;
  overflow-x: hidden;
}

body {
  color-scheme: light;
}

body :where(.rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl, .rounded-full) {
  border-radius: var(--sm-radius) !important;
}

body :where(button, a) {
  transition:
    background-color 170ms ease,
    border-color 170ms ease,
    color 170ms ease,
    box-shadow 170ms ease,
    transform 170ms ease;
}

body :where(button, a, input, textarea, select):focus-visible {
  outline: 2px solid rgb(0 82 255 / 60%);
  outline-offset: 3px;
}

body :where(input, textarea, select) {
  border: 1px solid var(--sm-line) !important;
  background: #ffffff !important;
  color: var(--sm-ink) !important;
  box-shadow: 0 1px 1px rgb(15 23 42 / 3%);
}

body :where(input, textarea, select)::placeholder {
  color: var(--sm-muted-2);
}

body .text-muted-foreground {
  color: var(--sm-muted) !important;
}

body .text-primary {
  color: var(--sm-blue) !important;
}

body .bg-primary {
  background: var(--sm-blue) !important;
  color: #ffffff !important;
}

body .bg-background,
body .bg-surface,
body .bg-muted,
body .bg-surface\/60,
body .bg-surface-elevated\/60,
body .bg-muted\/60 {
  background: var(--sm-panel) !important;
}

body .border-border,
body .border-input {
  border-color: var(--sm-line) !important;
}

body .sm-card,
.sm-dashboard-card,
.sm-rail-card,
.app-live-hero,
.app-live-stats,
.app-launch-feature,
.app-launch-tape,
.app-activity-console,
.sm-coin-identity,
.sm-coin-chart-card,
.sm-coin-about,
.sm-coin-metric,
.sm-coin-side-card,
.sm-coin-trade-card,
.sm-auth-page .sm-card {
  border: 1px solid var(--sm-line) !important;
  background: rgb(255 255 255 / 96%) !important;
  color: var(--sm-ink) !important;
  box-shadow:
    0 1px 2px rgb(15 23 42 / 4%),
    0 18px 54px rgb(15 23 42 / 7%);
}

body .sm-mono,
body code {
  color: var(--sm-ink-2);
}

.sm-home-rebuild,
.sm-marketing-header + main,
.sm-auth-page,
.sm-app-shell,
.app-live-page,
.sm-coin-page {
  min-height: 100vh;
  background: linear-gradient(180deg, #ffffff 0, var(--sm-page) 520px), var(--sm-page) !important;
  color: var(--sm-ink) !important;
}

.sm-marketing-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgb(223 229 239 / 86%);
  background: rgb(255 255 255 / 88%);
  backdrop-filter: blur(20px) saturate(1.25);
}

.sm-marketing-header-inner {
  width: min(100% - 48px, 1440px);
  min-height: 76px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: clamp(20px, 3vw, 44px);
}

.sm-logo {
  gap: 10px;
  color: var(--sm-ink);
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 850;
}

.sm-logo img {
  width: 40px;
  height: 40px;
  filter: drop-shadow(0 8px 18px rgb(0 82 255 / 12%));
}

.sm-marketing-header .sm-logo span {
  color: var(--sm-ink);
  font-size: 1.42rem;
  font-weight: 850;
}

.sm-marketing-nav {
  justify-content: center;
  gap: 6px;
  padding: 6px;
  border: 1px solid rgb(223 229 239 / 82%);
  border-radius: 999px;
  background: rgb(246 249 255 / 82%);
  font-size: 0.88rem;
  font-weight: 700;
}

.sm-marketing-nav a {
  min-height: 38px;
  border-radius: 999px;
  padding-inline: 16px;
  color: var(--sm-muted);
}

.sm-marketing-nav a::after {
  display: none;
}

.sm-marketing-nav a[data-active="true"],
.sm-marketing-nav a:hover {
  background: #ffffff;
  color: var(--sm-blue);
  box-shadow: 0 8px 22px rgb(15 23 42 / 7%);
}

.sm-header-actions {
  gap: 10px;
}

.sm-header-secondary,
.sm-header-primary,
.sm-button,
.app-live-link,
.sm-app-content :where(button, .inline-flex),
.sm-auth-page button {
  min-height: 44px;
  border-radius: var(--sm-radius) !important;
  padding-inline: 18px;
  font-weight: 750;
}

.sm-header-secondary,
.sm-button-secondary {
  border: 1px solid var(--sm-line);
  background: #ffffff;
  color: var(--sm-ink);
}

.sm-header-primary,
.sm-button-primary,
.app-live-link,
.sm-app-content :where(button.bg-primary, .bg-primary) {
  border: 1px solid var(--sm-blue) !important;
  background: var(--sm-blue) !important;
  color: #ffffff !important;
  box-shadow: 0 12px 26px rgb(0 82 255 / 20%);
}

.sm-header-primary:hover,
.sm-button-primary:hover,
.app-live-link:hover {
  background: var(--sm-blue-hover) !important;
  transform: translateY(-1px);
  box-shadow: 0 16px 34px rgb(0 82 255 / 26%);
}

.sm-header-secondary:hover,
.sm-button-secondary:hover,
.sm-app-content :where(button, .inline-flex):hover {
  border-color: rgb(0 82 255 / 34%) !important;
  background: var(--sm-blue-soft) !important;
  color: var(--sm-blue) !important;
}

.sm-hero {
  position: relative;
  overflow: clip;
  padding: clamp(38px, 6vw, 92px) 0 32px;
  background:
    linear-gradient(90deg, rgb(0 82 255 / 5%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(0 82 255 / 5%) 1px, transparent 1px),
    linear-gradient(180deg, #ffffff 0%, #f8fbff 58%, var(--sm-page) 100%);
  background-size:
    72px 72px,
    72px 72px,
    100% 100%;
}

.sm-hero::before {
  display: block;
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, #ffffff 0%, rgb(255 255 255 / 55%) 38%, rgb(255 255 255 / 0%) 78%),
    linear-gradient(180deg, rgb(255 255 255 / 0%) 72%, var(--sm-page) 100%);
  pointer-events: none;
}

.sm-hero-grid {
  position: relative;
  z-index: 1;
  width: min(100% - 48px, 1440px);
  gap: clamp(22px, 3vw, 42px);
}

.sm-hero-auth .sm-hero-grid {
  grid-template-areas:
    "copy product rail"
    "metrics product rail"
    "feed feed feed";
  grid-template-columns: minmax(360px, 0.9fr) minmax(520px, 1.08fr) minmax(286px, 0.52fr);
}

.sm-hero-public .sm-hero-grid {
  grid-template-areas:
    "copy product"
    "metrics product"
    "feed feed";
  grid-template-columns: minmax(440px, 0.9fr) minmax(560px, 1.1fr);
}

.sm-hero-copy {
  max-width: 650px;
  padding-top: clamp(20px, 4vw, 56px);
}

.sm-hero-eyebrow {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  gap: 10px;
  margin: 0 0 18px !important;
  border: 1px solid rgb(0 82 255 / 16%);
  border-radius: 999px;
  background: #ffffff;
  padding: 7px 12px;
  color: var(--sm-blue) !important;
  font-size: 0.82rem !important;
  font-weight: 750;
  box-shadow: 0 10px 30px rgb(15 23 42 / 5%);
}

.sm-hero-eyebrow span {
  display: block;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--sm-lime);
  box-shadow: 0 0 0 5px rgb(204 255 0 / 12%);
}

.sm-hero h1 {
  max-width: 720px;
  color: var(--sm-ink);
  font-size: clamp(4.3rem, 6.6vw, 7.65rem);
  font-weight: 850;
  letter-spacing: -0.03em;
  line-height: 0.9;
}

.sm-hero h1 span:last-child {
  color: var(--sm-blue);
}

.sm-hero-copy > p:not(.sm-hero-eyebrow) {
  max-width: 590px;
  margin-top: 24px;
  color: var(--sm-muted) !important;
  font-size: clamp(1.04rem, 1.3vw, 1.22rem);
  line-height: 1.6;
}

.sm-hero-actions {
  gap: 12px;
  margin-top: 30px;
}

.sm-hero-trust-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.sm-hero-trust-row span {
  border: 1px solid var(--sm-line);
  border-radius: 999px;
  background: rgb(255 255 255 / 82%);
  padding: 7px 10px;
  color: var(--sm-muted);
  font-size: 0.78rem;
  font-weight: 700;
}

.sm-hero-product-stage {
  position: relative;
  grid-area: product;
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: clamp(560px, 43vw, 690px);
  align-items: center;
  justify-items: end;
  isolation: isolate;
}

.sm-hero-product-stage .sm-hero-mascot {
  position: absolute;
  top: -34px;
  right: -28px;
  z-index: 1;
  width: min(46%, 285px);
  min-height: 280px;
  opacity: 0.98;
  pointer-events: none;
}

.sm-hero-product-stage .sm-hero-depth-scene {
  width: min(100%, 300px);
}

.sm-hero-product-stage .sm-hero-mascot-core {
  inset: 10%;
}

.sm-hero-product-stage .sm-hero-depth-grid {
  opacity: 0.5;
}

.sm-hero-product-stage .sm-hero-orbit {
  border-color: rgb(0 82 255 / 18%);
}

.sm-hero-product-stage .sm-hero-satellite {
  border-color: rgb(0 82 255 / 15%);
  background:
    linear-gradient(90deg, transparent 0 42%, rgb(0 82 255 / 32%) 42% 58%, transparent 58%),
    rgb(255 255 255 / 90%);
}

.sm-hero-product-panel {
  position: relative;
  z-index: 2;
  display: grid;
  width: min(100%, 680px);
  min-width: 0;
  max-width: 100%;
  gap: 16px;
  align-self: end;
  border: 1px solid rgb(199 208 222 / 88%);
  border-radius: var(--sm-radius);
  background: linear-gradient(180deg, rgb(255 255 255 / 96%), rgb(248 251 255 / 96%)), #ffffff;
  padding: clamp(18px, 2vw, 24px);
  box-shadow:
    0 1px 2px rgb(15 23 42 / 5%),
    0 32px 100px rgb(15 23 42 / 14%);
  animation: sm-product-panel-enter 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.sm-product-panel-head,
.sm-product-mini-head,
.sm-product-safe-row {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.sm-product-panel-head p,
.sm-product-mini-head span,
.sm-product-safe-row span {
  min-width: 0;
  color: var(--sm-muted);
  font-size: 0.82rem;
  font-weight: 700;
}

.sm-product-panel-head h2 {
  margin-top: 2px;
  color: var(--sm-ink);
  font-size: clamp(1.75rem, 2.3vw, 2.3rem);
  font-weight: 820;
  letter-spacing: -0.02em;
}

.sm-product-panel-head > span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgb(204 255 0 / 22%);
  border-radius: 999px;
  background: var(--sm-green-soft);
  padding: 7px 10px;
  color: var(--sm-lime);
  font-size: 0.76rem;
  font-weight: 800;
}

.sm-product-panel-head i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--sm-lime);
  box-shadow: 0 0 0 5px rgb(204 255 0 / 12%);
}

.sm-product-market-grid {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.85fr);
  gap: 12px;
}

.sm-product-market-grid article {
  min-width: 0;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: #ffffff;
  padding: 14px;
}

.sm-product-mini-head {
  min-height: 28px;
}

.sm-product-mini-head svg {
  color: var(--sm-blue);
}

.sm-product-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.sm-product-list > p {
  display: grid;
  min-height: 116px;
  place-items: center;
  border: 1px dashed var(--sm-line-strong);
  border-radius: var(--sm-radius-sm);
  color: var(--sm-muted);
  font-size: 0.84rem;
  text-align: center;
}

.sm-product-list a,
.sm-product-trader-list > div {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 48px;
  border: 1px solid transparent;
  border-radius: var(--sm-radius-sm);
  padding: 6px;
}

.sm-product-list a:hover {
  border-color: rgb(0 82 255 / 18%);
  background: var(--sm-blue-soft);
}

.sm-product-token-avatar,
.sm-product-trader-list > div > span:first-child {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: var(--sm-radius-sm);
  background: var(--sm-blue-soft);
  color: var(--sm-blue);
  font-size: 0.72rem;
  font-weight: 850;
  overflow: hidden;
}

.sm-product-token-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sm-product-list strong,
.sm-product-list small,
.sm-product-trader-list strong,
.sm-product-trader-list small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sm-product-list strong,
.sm-product-trader-list strong {
  color: var(--sm-ink);
  font-size: 0.86rem;
}

.sm-product-list small,
.sm-product-trader-list small {
  color: var(--sm-muted);
  font-size: 0.76rem;
}

.sm-product-list b,
.sm-product-trader-list b {
  color: var(--sm-lime);
  font-size: 0.78rem;
  font-weight: 800;
}

.sm-product-safe-row {
  justify-content: flex-start;
  border: 1px solid rgb(0 82 255 / 14%);
  border-radius: var(--sm-radius);
  background: var(--sm-blue-soft);
  padding: 12px 14px;
}

.sm-product-safe-row svg {
  flex: 0 0 auto;
  color: var(--sm-blue);
}

@keyframes sm-product-panel-enter {
  from {
    opacity: 0;
    transform: translate3d(0, 18px, 0) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

.sm-home-metrics {
  border: 0;
  gap: 10px;
  margin-top: 4px;
}

.sm-home-metrics div {
  min-height: 96px;
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius);
  background: rgb(255 255 255 / 88%);
  padding: 16px;
  box-shadow: 0 12px 34px rgb(15 23 42 / 5%);
}

.sm-home-metrics div:first-child {
  border-left: 1px solid var(--sm-line);
}

.sm-home-metrics svg {
  color: var(--sm-blue);
}

.sm-home-metrics strong {
  color: var(--sm-ink);
  font-size: clamp(1.35rem, 2vw, 1.9rem);
  letter-spacing: -0.03em;
}

.sm-home-metrics span {
  color: var(--sm-muted);
  font-weight: 700;
}

.sm-hero-feed-band::before {
  background: linear-gradient(90deg, transparent, rgb(0 82 255 / 32%), transparent);
}

.sm-hero-feed {
  border-color: var(--sm-line);
  background: #ffffff;
  box-shadow:
    0 1px 2px rgb(15 23 42 / 4%),
    0 24px 70px rgb(15 23 42 / 8%);
}

.sm-hero-feed-band .sm-hero-feed {
  background:
    linear-gradient(
      90deg,
      rgb(238 244 255 / 72%),
      transparent 24%,
      transparent 76%,
      rgb(236 253 243 / 58%)
    ),
    #ffffff;
}

.sm-hero-feed-head {
  min-height: 62px;
}

.sm-hero-feed-tabs span[data-active="true"] {
  color: var(--sm-blue);
}

.sm-hero-feed-tabs span[data-active="true"]::after {
  background: var(--sm-blue);
}

.sm-hero-feed select {
  background: #ffffff !important;
}

.sm-feed-avatar {
  border-color: rgb(0 82 255 / 16%);
  background: var(--sm-blue-soft);
  color: var(--sm-blue);
}

.sm-feed-main h3,
.sm-feed-main p,
.sm-feed-meta strong,
.sm-feed-full-link {
  color: var(--sm-ink);
}

.sm-feed-main code {
  border-color: rgb(0 82 255 / 15%);
  background: var(--sm-blue-soft);
  color: var(--sm-blue);
}

.sm-feed-side span {
  background: var(--sm-green-soft);
  color: var(--sm-lime);
}

.sm-hero-rail {
  gap: 12px;
}

.sm-rail-card {
  box-shadow:
    0 1px 2px rgb(15 23 42 / 4%),
    0 18px 46px rgb(15 23 42 / 7%);
}

.sm-portfolio-card {
  background: linear-gradient(180deg, #ffffff 0%, var(--sm-blue-wash) 100%) !important;
}

.sm-rail-title h2,
.sm-rail-card h2,
.sm-card-head h2 {
  color: var(--sm-ink);
  font-weight: 820;
}

.sm-portfolio-actions a {
  border: 1px solid var(--sm-line);
  border-radius: var(--sm-radius-sm);
  background: #ffffff;
  padding: 10px 6px;
}

.sm-portfolio-actions a:hover,
.sm-quick-list :where(a, button):not(:disabled):hover {
  border-color: rgb(0 82 255 / 18%);
  background: var(--sm-blue-soft);
  color: var(--sm-blue);
}

.sm-quick-list :where(a, button) {
  border: 1px solid transparent;
  border-radius: var(--sm-radius-sm);
  padding: 9px;
}

.sm-quick-list svg,
.sm-rules-card > svg {
  color: var(--sm-blue);
}

.sm-home-dashboard {
