/* Handcrafted product pass: softer, more editorial, and specific to thread-to-wallet commands. */
:root {
  --sm-paper: #fbfaf6;
  --sm-paper-2: #f3f0e8;
  --sm-cobalt: #0957ff;
  --sm-cobalt-2: #073fb8;
  --sm-forest: #257a43;
  --sm-graphite: #111318;
  --sm-soft-text: #596273;
  --sm-hairline: #dcd8ce;
  --sm-blue-soft: #edf4ff;
  --sm-blue-wash: #f7faff;
  --sm-page: #f7f5ef;
  --sm-line: #ded8cb;
  --sm-line-strong: #c8c0b1;
  --sm-muted: #596273;
  --sm-ink: #111318;
  --sm-blue: var(--sm-cobalt);
  --sm-lime: #ccff00;
}

.sm-home-rebuild,
.sm-marketing-header + main,
.app-live-page,
.sm-auth-page,
.sm-app-shell,
.sm-coin-page {
  background:
    linear-gradient(90deg, rgb(9 87 255 / 5%) 1px, transparent 1px),
