/* Second-pass launch polish: calmer rhythm, stronger contrast, and clearer section boundaries. */
:root {
  --sm-soft-text: #475261;
  --sm-muted: #4f5b68;
  --sm-page: #f6f3ec;
  --sm-paper: #fffdf8;
}

.sm-home-rebuild,
.sm-marketing-header + main {
  background: linear-gradient(180deg, #fffefd 0, #fbf8f0 30rem, var(--sm-page) 100%) !important;
  color: var(--sm-graphite);
}

.sm-home-rebuild :where(h1, h2, h3, .sm-logo) {
  letter-spacing: 0 !important;
}

.sm-home-rebuild :where(h1, h2) {
  text-wrap: balance;
}

.sm-home-rebuild :where(p, small, time) {
  text-wrap: pretty;
}

.sm-hero {
  border-bottom: 1px solid rgb(17 19 24 / 8%);
  background:
    linear-gradient(90deg, rgb(9 87 255 / 3.6%) 1px, transparent 1px),
    linear-gradient(180deg, rgb(17 19 24 / 3.2%) 1px, transparent 1px),
    linear-gradient(180deg, #fffefd 0%, #fbf8f0 64%, #f5f1e8 100%) !important;
  background-size:
    96px 96px,
    96px 96px,
    100% 100%;
  padding: clamp(54px, 6.4vw, 94px) 0 clamp(50px, 5vw, 76px);
}

.sm-hero::before {
  background:
    linear-gradient(90deg, #fffefd 0%, rgb(255 254 251 / 70%) 34%, rgb(255 254 251 / 0%) 78%),
    linear-gradient(180deg, rgb(255 254 251 / 0%) 66%, #f5f1e8 100%);
  opacity: 0.9;
}

.sm-hero-grid {
  width: min(100% - 64px, 1300px);
  gap: clamp(34px, 4.4vw, 78px);
  align-items: center;
}

.sm-hero-public .sm-hero-grid {
  grid-template-columns: minmax(400px, 0.86fr) minmax(520px, 1fr);
}

.sm-hero-auth .sm-hero-grid {
  grid-template-columns: minmax(340px, 0.82fr) minmax(500px, 1fr) minmax(268px, 0.5fr);
}

.sm-hero-intro {
  max-width: 620px;
  padding-top: clamp(8px, 2vw, 30px);
}

.sm-hero-eyebrow {
  gap: 9px;
  margin-bottom: 20px !important;
  border: 0 !important;
  border-left: 2px solid var(--sm-forest) !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 0 0 12px !important;
  color: var(--sm-forest) !important;
}

.sm-hero-eyebrow span {
  width: 6px;
  height: 6px;
  box-shadow: none !important;
}

.sm-hero h1 {
  max-width: 650px;
  color: var(--sm-graphite);
  font-size: clamp(3.85rem, 5.35vw, 6.35rem);
  font-weight: 820;
  line-height: 0.96;
}

.sm-hero h1 span:last-child {
  color: var(--sm-cobalt);
}

.sm-hero-intro > p:not(.sm-hero-eyebrow),
.sm-hero .sm-hero-intro > p:not(.sm-hero-eyebrow) {
  max-width: 540px;
  color: var(--sm-soft-text) !important;
  font-size: clamp(1.02rem, 1.15vw, 1.15rem);
  line-height: 1.66;
}

.sm-hero-actions {
  margin-top: 28px;
}

.sm-hero-trust-row {
  width: min(100%, 560px);
  gap: 0;
  margin-top: 24px;
  border-top: 1px solid rgb(17 19 24 / 12%);
  padding-top: 12px;
}

.sm-hero-trust-row span {
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  padding: 0 16px 0 0;
  color: #4b5563;
  font-size: 0.79rem;
  font-weight: 740;
}

.sm-hero-trust-row span + span {
  border-left: 1px solid rgb(17 19 24 / 12%) !important;
  padding-left: 16px;
}

.sm-hero-product-stage {
  min-height: clamp(520px, 39vw, 640px);
}

.sm-hero-product-stage .sm-hero-mascot {
  top: -14px;
