/* Dashboard modal system: Rayo-inspired portal surfaces shared by wallet and pools flows. */

body [role="dialog"].app-dashboard-modal,
body [role="alertdialog"].app-dashboard-modal {
  --modal-bg: var(--app-bg, #faf7f6);
  --modal-panel: var(--app-panel, #ffffff);
  --modal-soft: var(--app-soft, #f1ede9);
  --modal-ink: var(--app-ink, #111111);
  --modal-ink-2: var(--app-ink-2, #303030);
  --modal-muted: var(--app-muted, #585858);
  --modal-faint: var(--app-faint, #b2aead);
  --modal-line: var(--app-line, rgb(17 17 17 / 8%));
  --modal-lime: var(--app-lime, #ccff00);
  --modal-warning-ink: var(--app-warning-ink, #7a5a00);
  --modal-warning-soft: var(--app-warning-soft, rgb(255 207 102 / 28%));
  width: min(calc(100vw - 32px), 600px) !important;
  max-height: min(calc(100dvh - 32px), 720px) !important;
  overflow: hidden !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 20px !important;
  border: 0 !important;
  border-radius: 32px !important;
  background: var(--modal-panel) !important;
  padding: clamp(24px, 4vw, 34px) !important;
  color: var(--modal-ink) !important;
  -webkit-text-fill-color: var(--modal-ink) !important;
  box-shadow: none !important;
  font-family: var(--rayo-font, var(--font-sans)) !important;
}

body [role="dialog"].app-dashboard-modal > button {
  top: 22px !important;
  right: 22px !important;
  display: grid !important;
  width: 38px !important;
  height: 38px !important;
  place-items: center !important;
  border: 0 !important;
  border-radius: 999px !important;
  background: var(--modal-soft) !important;
  color: var(--modal-ink) !important;
  -webkit-text-fill-color: var(--modal-ink) !important;
  opacity: 1 !important;
  box-shadow: none !important;
}

body [role="dialog"].app-dashboard-modal > button:is(:hover, :focus-visible) {
  background: var(--modal-lime) !important;
  color: #111111 !important;
  -webkit-text-fill-color: #111111 !important;
}

body .app-dashboard-modal-header {
  flex: 0 0 auto !important;
  display: grid !important;
  gap: 10px !important;
  padding-right: 42px !important;
}

body .app-dashboard-modal h2 {
  max-width: 100% !important;
  margin: 0 !important;
  color: var(--modal-ink) !important;
  -webkit-text-fill-color: var(--modal-ink) !important;
  font-family: var(--rayo-display, var(--font-display)) !important;
  font-size: clamp(2.05rem, 5vw, 3rem) !important;
  font-weight: 850 !important;
  letter-spacing: 0 !important;
  line-height: 0.95 !important;
}

body
  .app-dashboard-modal
  :where([data-radix-dialog-description], [data-radix-alert-dialog-description]) {
  max-width: 44rem !important;
  margin: 0 !important;
  color: var(--modal-muted) !important;
  -webkit-text-fill-color: var(--modal-muted) !important;
  font-size: 0.98rem !important;
  line-height: 1.5 !important;
}

body .app-dashboard-modal-body,
body .app-dashboard-modal-form,
body .app-pools-dialog-body {
  flex: 1 1 auto !important;
  min-height: 0 !important;
  display: grid !important;
  gap: 16px !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  overscroll-behavior: contain !important;
  padding-right: 4px !important;
