/* ============================================================
   Coin comments (cc-*) — matches sm-coin card system
   ============================================================ */
body .sm-coin-page .cc-section {
  position: relative;
  display: grid;
  gap: 18px;
  padding: clamp(20px, 2.4vw, 30px);
  border: 0;
  border-radius: 34px;
  background:
    linear-gradient(135deg, rgb(250 247 246 / 6%) 0 1px, transparent 1px 36px),
    linear-gradient(180deg, rgb(250 247 246 / 8%), rgb(250 247 246 / 3%));
  color: var(--coin-paper);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 8%);
}
.cc-header {
  display: grid;
  gap: 4px;
}
.cc-header-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--coin-paper);
}
.cc-header-title h2 {
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  margin: 0;
}
.cc-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgb(159 139 231 / 18%);
  color: rgb(247 244 229 / 92%);
  font-size: 0.72rem;
  font-weight: 800;
}
.cc-header-sub {
  margin: 0;
  color: rgb(247 244 229 / 60%);
  font-size: 0.85rem;
  font-weight: 600;
}

body .sm-coin-page .cc-composer {
  display: grid;
  gap: 10px;
  padding: 14px;
  border-radius: 24px;
  background: rgb(10 10 12 / 55%);
  border: 0;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 6%);
}
body .sm-coin-page .cc-composer--compact {
  padding: 10px;
  border-radius: 20px;
  margin-top: 10px;
  background: rgb(10 10 12 / 45%);
}
body .sm-coin-page .cc-textarea,
body .sm-coin-page textarea.cc-textarea {
  width: 100%;
  min-height: 60px;
  padding: 10px 12px;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  border-radius: 16px;
  background: transparent !important;
  color: var(--coin-paper) !important;
  font: inherit;
  font-size: 0.94rem;
  resize: vertical;
}
body .sm-coin-page .cc-textarea::placeholder {
  color: rgb(247 244 229 / 42%) !important;
}
body .sm-coin-page .cc-textarea:focus,
body .sm-coin-page .cc-textarea:focus-visible {
  background: transparent !important;
  color: var(--coin-paper) !important;
  outline: 0 !important;
  box-shadow: none !important;
}
body .sm-coin-page .cc-textarea:-webkit-autofill,
body .sm-coin-page .cc-textarea:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--coin-paper) !important;
  -webkit-box-shadow: 0 0 0px 1000px rgb(10 10 12 / 90%) inset !important;
  caret-color: var(--coin-paper) !important;
}
.cc-composer-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.cc-remaining {
  color: rgb(247 244 229 / 42%);
  font-size: 0.75rem;
  font-weight: 700;
}
.cc-remaining.is-low {
  color: #ff9a55;
}
.cc-submit {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 18px;
  border: 0;
  border-radius: 999px;
  background: var(--coin-lime, #ccff00);
  color: #111;
  font-weight: 800;
  font-size: 0.86rem;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    filter 0.15s ease;
}
.cc-submit:hover:not(:disabled) {
  filter: brightness(1.05);
  transform: translateY(-1px);
}
.cc-submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.cc-list {
  display: grid;
  gap: 4px;
}
.cc-empty {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 22px 4px;
  color: rgb(247 244 229 / 55%);
  font-size: 0.9rem;
  font-weight: 600;
}

.cc-item {
  display: grid;
  grid-template-columns: 40px 1fr;
  gap: 12px;
  padding: 14px 4px;
  border-top: 0;
}
.cc-list {
  gap: 6px;
}

.cc-avatar {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  overflow: hidden;
  background: linear-gradient(135deg, rgb(159 139 231 / 55%), rgb(204 255 0 / 45%));
  color: #111;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 0.95rem;
  flex-shrink: 0;
}
.cc-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.cc-body {
  min-width: 0;
  display: grid;
  gap: 6px;
}
.cc-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  color: rgb(247 244 229 / 88%);
  font-size: 0.85rem;
}
.cc-name {
  font-weight: 800;
}
.cc-handle {
  color: rgb(247 244 229 / 50%);
  font-weight: 600;
}
.cc-dot {
  color: rgb(247 244 229 / 35%);
}
.cc-time {
  color: rgb(247 244 229 / 50%);
  font-weight: 600;
}
.cc-text {
  margin: 0;
  color: var(--coin-paper);
  font-size: 0.95rem;
  line-height: 1.5;
  white-space: pre-wrap;
  word-wrap: break-word;
}

.cc-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}
.cc-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgb(247 244 229 / 62%);
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}
.cc-action:hover {
  background: rgb(250 247 246 / 6%);
  color: var(--coin-paper);
}
.cc-like.is-liked {
  color: #ff5d8f;
  background: rgb(255 93 143 / 12%);
}
.cc-like.is-liked:hover {
  background: rgb(255 93 143 / 18%);
}

.cc-replies {
  display: grid;
  margin-top: 6px;
  padding-left: 14px;
  border-left: 0;
  box-shadow: inset 2px 0 0 rgb(204 255 0 / 18%);
}
.cc-replies .cc-item {
  border-top: 0;
  padding: 10px 0;
  grid-template-columns: 32px 1fr;
  gap: 10px;
}
.cc-replies .cc-avatar {
  width: 32px;
  height: 32px;
  font-size: 0.8rem;
}

.cc-spin {
  animation: cc-spin 0.9s linear infinite;
}
@keyframes cc-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 720px) {
  body .sm-coin-page .cc-section {
    padding: 18px;
    border-radius: 26px;
  }
  .cc-item {
    grid-template-columns: 34px 1fr;
    gap: 10px;
  }
  .cc-avatar {
    width: 34px;
    height: 34px;
    font-size: 0.85rem;
  }
}

